window.__QR["data/core/9.json"]={"v":[["بَرَآءَةٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ","Freedom from obligation (is proclaimed) from Allah and His messenger toward those of the idolaters with whom ye made a treaty"],["فَسِيحُواْ فِي ٱلۡأَرۡضِ أَرۡبَعَةَ أَشۡهُرٖ وَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِ وَأَنَّ ٱللَّهَ مُخۡزِي ٱلۡكَٰفِرِينَ","Travel freely in the land four months, and know that ye cannot escape Allah and that Allah will confound the disbelievers (in His Guidance)"],["وَأَذَٰنٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِيٓءٞ مِّنَ ٱلۡمُشۡرِكِينَ وَرَسُولُهُۥۚ فَإِن تُبۡتُمۡ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُواْ بِعَذَابٍ أَلِيمٍ","And a proclamation from Allah and His messenger to all men on the day of the Greater Pilgrimage that Allah is free from obligation to the idolaters, and (so is) His messenger. So, if ye repent, it will be better for you; but if ye are averse, then know that ye cannot escape Allah. Give tidings (O Muhammad) of a painful doom to those who disbelieve"],["إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ثُمَّ لَمۡ يَنقُصُوكُمۡ شَيۡـٔٗا وَلَمۡ يُظَٰهِرُواْ عَلَيۡكُمۡ أَحَدٗا فَأَتِمُّوٓاْ إِلَيۡهِمۡ عَهۡدَهُمۡ إِلَىٰ مُدَّتِهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ","Excepting those of the idolaters with whom ye (Muslims) have a treaty, and who have since abated nothing of your right nor have supported anyone against you. (As for these), fulfil their treaty to them till their term. Lo! Allah loveth those who keep their duty (unto Him)"],["فَإِذَا ٱنسَلَخَ ٱلۡأَشۡهُرُ ٱلۡحُرُمُ فَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ حَيۡثُ وَجَدتُّمُوهُمۡ وَخُذُوهُمۡ وَٱحۡصُرُوهُمۡ وَٱقۡعُدُواْ لَهُمۡ كُلَّ مَرۡصَدٖۚ فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","Then, when the sacred months have passed, slay the idolaters wherever ye find them, and take them (captive), and besiege them, and prepare for them each ambush. But if they repent and establish worship and pay the poor-due, then leave their way free. Lo! Allah is Forgiving, Merciful"],["وَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡلَمُونَ","And if anyone of the idolaters seeketh thy protection (O Muhammad), then protect him so that he may hear the Word of Allah, and afterward convey him to his place of safety. That is because they are a folk who know not"],["كَيۡفَ يَكُونُ لِلۡمُشۡرِكِينَ عَهۡدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ فَمَا ٱسۡتَقَٰمُواْ لَكُمۡ فَٱسۡتَقِيمُواْ لَهُمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ","How can there be a treaty with Allah and with His messenger for the idolaters save those with whom ye made a treaty at the Inviolable Place of Worship? So long as they are true to you, be true to them. Lo! Allah loveth those who keep their duty"],["كَيۡفَ وَإِن يَظۡهَرُواْ عَلَيۡكُمۡ لَا يَرۡقُبُواْ فِيكُمۡ إِلّٗا وَلَا ذِمَّةٗۚ يُرۡضُونَكُم بِأَفۡوَٰهِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ فَٰسِقُونَ","How (can there be any treaty for the others) when, if they have the upper hand of you, they regard not pact nor honour in respect of you? They satisfy you with their mouths the while their hearts refuse. And most of them are wrongdoers"],["ٱشۡتَرَوۡاْ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلٗا فَصَدُّواْ عَن سَبِيلِهِۦٓۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ","They have purchased with the revelations of Allah a little gain, so they debar (men) from His way. Lo! evil is that which they are wont to do"],["لَا يَرۡقُبُونَ فِي مُؤۡمِنٍ إِلّٗا وَلَا ذِمَّةٗۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُعۡتَدُونَ","And they observe toward a believer neither pact nor honour. These are they who are transgressors"],["فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِۗ وَنُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ","But if they repent and establish worship and pay the poor-due, then are they your brethren in religion. We detail Our revelations for a people who have knowledge"],["وَإِن نَّكَثُوٓاْ أَيۡمَٰنَهُم مِّنۢ بَعۡدِ عَهۡدِهِمۡ وَطَعَنُواْ فِي دِينِكُمۡ فَقَٰتِلُوٓاْ أَئِمَّةَ ٱلۡكُفۡرِ إِنَّهُمۡ لَآ أَيۡمَٰنَ لَهُمۡ لَعَلَّهُمۡ يَنتَهُونَ","And if they break their pledges after their treaty (hath been made with you) and assail your religion, then fight the heads of disbelief - Lo! they have no binding oaths - in order that they may desist"],["أَلَا تُقَٰتِلُونَ قَوۡمٗا نَّكَثُوٓاْ أَيۡمَٰنَهُمۡ وَهَمُّواْ بِإِخۡرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمۡ أَوَّلَ مَرَّةٍۚ أَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِينَ","Will ye not fight a folk who broke their solemn pledges, and purposed to drive out the messenger and did attack you first? What! Fear ye them? Now Allah hath more right that ye should fear Him, if ye are believers"],["قَٰتِلُوهُمۡ يُعَذِّبۡهُمُ ٱللَّهُ بِأَيۡدِيكُمۡ وَيُخۡزِهِمۡ وَيَنصُرۡكُمۡ عَلَيۡهِمۡ وَيَشۡفِ صُدُورَ قَوۡمٖ مُّؤۡمِنِينَ","Fight them! Allah will chastise them at your hands, and He will lay them low and give you victory over them, and He will heal the breasts of folk who are believers"],["وَيُذۡهِبۡ غَيۡظَ قُلُوبِهِمۡۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ","And He will remove the anger of their hearts. Allah relenteth toward whom He will. Allah is Knower, Wise"],["أَمۡ حَسِبۡتُمۡ أَن تُتۡرَكُواْ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَلَمۡ يَتَّخِذُواْ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلۡمُؤۡمِنِينَ وَلِيجَةٗۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ","Or deemed ye that ye would be left (in peace) when Allah yet knoweth not those of you who strive, choosing for familiar none save Allah and His messenger and the believers? Allah is Informed of what ye do"],["مَا كَانَ لِلۡمُشۡرِكِينَ أَن يَعۡمُرُواْ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلۡكُفۡرِۚ أُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ وَفِي ٱلنَّارِ هُمۡ خَٰلِدُونَ","It is not for the idolaters to tend Allah's sanctuaries, bearing witness against themselves of disbelief. As for such, their works are vain and in the Fire they will abide"],["إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ أُوْلَـٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ","He only shall tend Allah's sanctuaries who believeth in Allah and the Last Day and observeth proper worship and payeth the poor-due and feareth none save Allah. For such (only) is it possible that they can be of the rightly guided"],["۞أَجَعَلۡتُمۡ سِقَايَةَ ٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ","Count ye the slaking of a pilgrim's thirst and tendance of the Inviolable Place of Worship as (equal to the worth of) him who believeth in Allah and the Last Day, and striveth in the way of Allah? They are not equal in the sight of Allah. Allah guideth not wrongdoing folk"],["ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ","Those who believe, and have left their homes and striven with their wealth and their lives in Allah's way are of much greater worth in Allah's sight. These are they who are triumphant"],["يُبَشِّرُهُمۡ رَبُّهُم بِرَحۡمَةٖ مِّنۡهُ وَرِضۡوَٰنٖ وَجَنَّـٰتٖ لَّهُمۡ فِيهَا نَعِيمٞ مُّقِيمٌ","Their Lord giveth them good tidings of mercy from Him, and acceptance, and Gardens where enduring pleasure will be theirs"],["خَٰلِدِينَ فِيهَآ أَبَدًاۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ","There they will abide for ever. Lo! with Allah there is immense reward"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُوٓاْ ءَابَآءَكُمۡ وَإِخۡوَٰنَكُمۡ أَوۡلِيَآءَ إِنِ ٱسۡتَحَبُّواْ ٱلۡكُفۡرَ عَلَى ٱلۡإِيمَٰنِۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ","O ye who believe! Choose not your fathers nor your brethren for friends if they take pleasure in disbelief rather than faith. Whoso of you taketh them for friends, such are wrong-doers"],["قُلۡ إِن كَانَ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ وَإِخۡوَٰنُكُمۡ وَأَزۡوَٰجُكُمۡ وَعَشِيرَتُكُمۡ وَأَمۡوَٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَٰرَةٞ تَخۡشَوۡنَ كَسَادَهَا وَمَسَٰكِنُ تَرۡضَوۡنَهَآ أَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ فِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ","Say: If your fathers, and your sons, and your brethren, and your wives, and your tribe, and the wealth ye have acquired, and merchandise for which ye fear that there will no sale, and dwellings ye desire are dearer to you than Allah and His messenger and striving in His way: then wait till Allah bringeth His command to pass. Allah guideth not wrongdoing folk"],["لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِي مَوَاطِنَ كَثِيرَةٖ وَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَيۡـٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ","Allah hath given you victory on many fields and on the day of Huneyn, when ye exulted in your multitude but it availed you naught, and the earth, vast as it is, was straitened for you; then ye turned back in flight"],["ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَنزَلَ جُنُودٗا لَّمۡ تَرَوۡهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُواْۚ وَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ","Then Allah sent His peace of reassurance down upon His messenger and upon the believers, and sent down hosts ye could not see, and punished those who disbelieved. Such is the reward of disbelievers"],["ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعۡدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","Then afterward Allah will relent toward whom He will; for Allah is Forgiving, Merciful"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ فَلَا يَقۡرَبُواْ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَٰذَاۚ وَإِنۡ خِفۡتُمۡ عَيۡلَةٗ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن شَآءَۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٞ","O ye who believe! The idolaters only are unclean. So let them not come near the Inviolable Place of Worship after this their year. If ye fear poverty (from the loss of their merchandise) Allah shall preserve you of His bounty if He will. Lo! Allah is Knower, Wise"],["قَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حَتَّىٰ يُعۡطُواْ ٱلۡجِزۡيَةَ عَن يَدٖ وَهُمۡ صَٰغِرُونَ","Fight against such of those who have been given the Scripture as believe not in Allah nor the Last Day, and forbid not that which Allah hath forbidden by His messenger, and follow not the Religion of Truth, until they pay the tribute readily, being brought low"],["وَقَالَتِ ٱلۡيَهُودُ عُزَيۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلۡمَسِيحُ ٱبۡنُ ٱللَّهِۖ ذَٰلِكَ قَوۡلُهُم بِأَفۡوَٰهِهِمۡۖ يُضَٰهِـُٔونَ قَوۡلَ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ","And the Jews say: Ezra is the son of Allah, and the Christians say: The Messiah is the son of Allah. That is their saying with their mouths. They imitate the saying of those who disbelieved of old. Allah (Himself) fighteth against them. How perverse are they"],["ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابٗا مِّن دُونِ ٱللَّهِ وَٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُوٓاْ إِلَٰهٗا وَٰحِدٗاۖ لَّآ إِلَٰهَ إِلَّا هُوَۚ سُبۡحَٰنَهُۥ عَمَّا يُشۡرِكُونَ","They have taken as lords beside Allah their rabbis and their monks and the Messiah son of Mary, when they were bidden to worship only One Allah. There is no Allah save Him. Be He Glorified from all that they ascribe as partner (unto Him)"],["يُرِيدُونَ أَن يُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَيَأۡبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ","Fain would they put out the light of Allah with their mouths, but Allah disdaineth (aught) save that He shall perfect His light, however much the disbelievers are averse"],["هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ","He it is Who hath sent His messenger with the guidance and the Religion of Truth, that He may cause it to prevail over all religion, however much the idolaters may be averse"],["۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ","O ye who believe! Lo! many of the (Jewish) rabbis and the (Christian) monks devour the wealth of mankind wantonly and debar (men) from the way of Allah. They who hoard up gold and silver and spend it not in the way of Allah, unto them give tidings (O Muhammad) of a painful doom"],["يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ","On the day when it will (all) be heated in the fire of hell, and their foreheads and their flanks and their backs will be branded therewith (and it will be said unto them): Here is that which ye hoarded for yourselves. Now taste of what ye used to hoard"],["إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا فِي كِتَٰبِ ٱللَّهِ يَوۡمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ مِنۡهَآ أَرۡبَعَةٌ حُرُمٞۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُۚ فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ كَمَا يُقَٰتِلُونَكُمۡ كَآفَّةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ","Lo! the number of the months with Allah is twelve months by Allah's ordinance in the day that He created the heavens and the earth. Four of them are sacred: that is the right religion. So wrong not yourselves in them. And wage war on all of the idolaters as they are waging war on all of you. And know that Allah is with those who keep their duty (unto Him)"],["إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُواْ يُحِلُّونَهُۥ عَامٗا وَيُحَرِّمُونَهُۥ عَامٗا لِّيُوَاطِـُٔواْ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّواْ مَا حَرَّمَ ٱللَّهُۚ زُيِّنَ لَهُمۡ سُوٓءُ أَعۡمَٰلِهِمۡۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ","Postponement (of a sacred month) is only an excess of disbelief whereby those who disbelieve are misled; they allow it one year and forbid it (another) year, that they may make up the number of the months which Allah hath hallowed, so that they allow that which Allah hath forbidden. The evil of their deeds is made fairseeming unto them. Allah guideth not the disbelieving folk"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ","O ye who believe! What aileth you that when it is said unto you: Go forth in the way of Allah, ye are bowed down to the ground with heaviness. Take ye pleasure in the life of the world rather than in the Hereafter? The comfort of the life of the world is but little in the Hereafter"],["إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","If ye go not forth He will afflict you with a painful doom, and will choose instead of you a folk other than you. Ye cannot harm Him at all. Allah is Able to do all things"],["إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ","If ye help him not, still Allah helped him when those who disbelieve drove him forth, the second of two; when they two were in the cave, when he said unto his comrade: Grieve not. Lo! Allah is with us. Then Allah caused His peace of reassurance to descend upon him and supported him with hosts ye cannot see, and made the word of those who disbelieved the nethermost, while Allah's Word it was that became the uppermost. Allah is Mighty, Wise"],["ٱنفِرُواْ خِفَافٗا وَثِقَالٗا وَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","Go forth, light-armed and heavy-armed, and strive with your wealth and your lives in the way of Allah! That is best for you if ye but knew"],["لَوۡ كَانَ عَرَضٗا قَرِيبٗا وَسَفَرٗا قَاصِدٗا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتۡ عَلَيۡهِمُ ٱلشُّقَّةُۚ وَسَيَحۡلِفُونَ بِٱللَّهِ لَوِ ٱسۡتَطَعۡنَا لَخَرَجۡنَا مَعَكُمۡ يُهۡلِكُونَ أَنفُسَهُمۡ وَٱللَّهُ يَعۡلَمُ إِنَّهُمۡ لَكَٰذِبُونَ","Had it been a near adventure and an easy journey they had followed thee, but the distance seemed too far for them. Yet will they swear by Allah (saying): If we had been able we would surely have set out with you. They destroy their souls, and Allah knoweth that they verily are liars"],["عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُواْ وَتَعۡلَمَ ٱلۡكَٰذِبِينَ","Allah forgive thee (O Muhammad)! Wherefor didst thou grant them leave ere those who told the truth were manifest to thee and thou didst know the liars"],["لَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ","Those who believe in Allah and the Last Day ask no leave of thee lest they should strive with their wealth and their lives. Allah is Aware of those who keep their duty (unto Him)"],["إِنَّمَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱرۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ فِي رَيۡبِهِمۡ يَتَرَدَّدُونَ","They alone ask leave of thee who believe not in Allah and the Last Day, and whose hearts feel doubt, so in their doubt they waver"],["۞وَلَوۡ أَرَادُواْ ٱلۡخُرُوجَ لَأَعَدُّواْ لَهُۥ عُدَّةٗ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِيلَ ٱقۡعُدُواْ مَعَ ٱلۡقَٰعِدِينَ","And if they had wished to go forth they would assuredly have made ready some equipment, but Allah was averse to their being sent forth and held them back and it was said (unto them): Sit ye with the sedentary"],["لَوۡ خَرَجُواْ فِيكُم مَّا زَادُوكُمۡ إِلَّا خَبَالٗا وَلَأَوۡضَعُواْ خِلَٰلَكُمۡ يَبۡغُونَكُمُ ٱلۡفِتۡنَةَ وَفِيكُمۡ سَمَّـٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ","Had they gone forth among you they had added to you naught save trouble and had hurried to and fro among you, seeking to cause sedition among you; and among you there are some who would have listened to them. Allah is Aware of evil-doers"],["لَقَدِ ٱبۡتَغَوُاْ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ حَتَّىٰ جَآءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَٰرِهُونَ","Aforetime they sought to cause sedition and raised difficulties for thee till the Truth came and the decree of Allah was made manifest, though they were loth"],["وَمِنۡهُم مَّن يَقُولُ ٱئۡذَن لِّي وَلَا تَفۡتِنِّيٓۚ أَلَا فِي ٱلۡفِتۡنَةِ سَقَطُواْۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ","Of them is he who saith: Grant me leave (to stay at home) and tempt me not. Surely it is into temptation that they (thus) have fallen. Lo! hell verily is all around the disbelievers"],["إِن تُصِبۡكَ حَسَنَةٞ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ مُصِيبَةٞ يَقُولُواْ قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ وَيَتَوَلَّواْ وَّهُمۡ فَرِحُونَ","If good befalleth thee (O Muhammad) it afflicteth them, and if calamity befalleth thee, they say: We took precaution, and they turn away well pleased"],["قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ","Say: Naught befalleth us save that which Allah hath decreed for us. He is our Protecting Friend. In Allah let believers put their trust"],["قُلۡ هَلۡ تَرَبَّصُونَ بِنَآ إِلَّآ إِحۡدَى ٱلۡحُسۡنَيَيۡنِۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٖ مِّنۡ عِندِهِۦٓ أَوۡ بِأَيۡدِينَاۖ فَتَرَبَّصُوٓاْ إِنَّا مَعَكُم مُّتَرَبِّصُونَ","Say: Can ye await for us aught save one of two good things (death or victory in Allah's way)? while we await for you that Allah will afflict you with a doom from Him or at our hands. Await then! Lo! We are awaiting with you"],["قُلۡ أَنفِقُواْ طَوۡعًا أَوۡ كَرۡهٗا لَّن يُتَقَبَّلَ مِنكُمۡ إِنَّكُمۡ كُنتُمۡ قَوۡمٗا فَٰسِقِينَ","Say: Pay (your contribution), willingly or unwillingly, it will not be accepted from you. Lo! ye were ever froward folk"],["وَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَٰتُهُمۡ إِلَّآ أَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأۡتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمۡ كَٰرِهُونَ","And naught preventeth that their contributions should be accepted from them save that they have disbelieved in Allah and in His messenger, and they come not to worship save as idlers, and pay not (their contribution) save reluctantly"],["فَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ","So let not their riches nor their children please thee (O Muhammad). Allah thereby intendeth but to punish them in the life of the world and that their souls shall pass away while they are disbelievers"],["وَيَحۡلِفُونَ بِٱللَّهِ إِنَّهُمۡ لَمِنكُمۡ وَمَا هُم مِّنكُمۡ وَلَٰكِنَّهُمۡ قَوۡمٞ يَفۡرَقُونَ","And they swear by Allah that they are in truth of you, when they are not of you, but they are folk who are afraid"],["لَوۡ يَجِدُونَ مَلۡجَـًٔا أَوۡ مَغَٰرَٰتٍ أَوۡ مُدَّخَلٗا لَّوَلَّوۡاْ إِلَيۡهِ وَهُمۡ يَجۡمَحُونَ","Had they but found a refuge, or caverns, or a place to enter, they surely had resorted thither swift as runaways"],["وَمِنۡهُم مَّن يَلۡمِزُكَ فِي ٱلصَّدَقَٰتِ فَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا هُمۡ يَسۡخَطُونَ","And of them is he who defameth thee in the matter of the alms. If they are given thereof they are content, and if they are not given thereof, behold! they are enraged"],["وَلَوۡ أَنَّهُمۡ رَضُواْ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُواْ حَسۡبُنَا ٱللَّهُ سَيُؤۡتِينَا ٱللَّهُ مِن فَضۡلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ","(How much more seemly) had they been content with that which Allah and His messenger had given them and had said: Allah sufficeth us. Allah will give us of His bounty, and (also) His messenger. Unto Allah we are suppliants"],["۞إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ فَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","The alms are only for the poor and the needy, and those who collect them, and those whose hearts are to be reconciled, and to free the captives and the debtors, and for the cause of Allah, and (for) the wayfarer; a duty imposed by Allah. Allah is Knower, Wise"],["وَمِنۡهُمُ ٱلَّذِينَ يُؤۡذُونَ ٱلنَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٞۚ قُلۡ أُذُنُ خَيۡرٖ لَّكُمۡ يُؤۡمِنُ بِٱللَّهِ وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ وَرَحۡمَةٞ لِّلَّذِينَ ءَامَنُواْ مِنكُمۡۚ وَٱلَّذِينَ يُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِيمٞ","And of them are those who vex the Prophet and say: He is only a hearer. Say: A hearer of good for you, who believeth in Allah and is true to the believers, and a mercy for such of you as believe. Those who vex the messenger of Allah, for them there is a painful doom"],["يَحۡلِفُونَ بِٱللَّهِ لَكُمۡ لِيُرۡضُوكُمۡ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرۡضُوهُ إِن كَانُواْ مُؤۡمِنِينَ","They swear by Allah to you (Muslims) to please you, but Allah, with His messenger, hath more right that they should please Him if they are believers"],["أَلَمۡ يَعۡلَمُوٓاْ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدٗا فِيهَاۚ ذَٰلِكَ ٱلۡخِزۡيُ ٱلۡعَظِيمُ","Know they not that whoso opposeth Allah and His messenger, his verily is fire of hell, to abide therein? That is the extreme abasement"],["يَحۡذَرُ ٱلۡمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيۡهِمۡ سُورَةٞ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوٓاْ إِنَّ ٱللَّهَ مُخۡرِجٞ مَّا تَحۡذَرُونَ","The hypocrites fear lest a surah should be revealed concerning them, proclaiming what is in their hearts. Say: Scoff (your fill)! Lo! Allah is disclosing what ye fear"],["وَلَئِن سَأَلۡتَهُمۡ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ","And if thou ask them (O Muhammad) they will say: We did but talk and jest. Say: Was it at Allah and His revelations and His messenger that ye did scoff"],["لَا تَعۡتَذِرُواْ قَدۡ كَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡۚ إِن نَّعۡفُ عَن طَآئِفَةٖ مِّنكُمۡ نُعَذِّبۡ طَآئِفَةَۢ بِأَنَّهُمۡ كَانُواْ مُجۡرِمِينَ","Make no excuse. Ye have disbelieved after your (confession of) belief. If We forgive a party of you, a party of you We shall punish because they have been guilty"],["ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ بَعۡضُهُم مِّنۢ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمُنكَرِ وَيَنۡهَوۡنَ عَنِ ٱلۡمَعۡرُوفِ وَيَقۡبِضُونَ أَيۡدِيَهُمۡۚ نَسُواْ ٱللَّهَ فَنَسِيَهُمۡۚ إِنَّ ٱلۡمُنَٰفِقِينَ هُمُ ٱلۡفَٰسِقُونَ","The hypocrites, both men and women, proceed one from another. They enjoin the wrong, and they forbid the right, and they withhold their hands (from spending for the cause of Allah). They forget Allah, so He hath forgotten them. Lo! the hypocrites, they are the transgressors"],["وَعَدَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۚ هِيَ حَسۡبُهُمۡۚ وَلَعَنَهُمُ ٱللَّهُۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ","Allah promiseth the hypocrites, both men and women, and the disbelievers fire of hell for their abode. It will suffice them. Allah curseth them, and theirs is lasting torment"],["كَٱلَّذِينَ مِن قَبۡلِكُمۡ كَانُوٓاْ أَشَدَّ مِنكُمۡ قُوَّةٗ وَأَكۡثَرَ أَمۡوَٰلٗا وَأَوۡلَٰدٗا فَٱسۡتَمۡتَعُواْ بِخَلَٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِينَ مِن قَبۡلِكُم بِخَلَٰقِهِمۡ وَخُضۡتُمۡ كَٱلَّذِي خَاضُوٓاْۚ أُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ","Even as those before you who were mightier than you in strength, and more affluent than you in wealth and children. They enjoyed their lot awhile, so ye enjoy your lot awhile even as those before you did enjoy their lot awhile. And ye prate even as they prated. Such are they whose works have perished in the world and the Hereafter. Such are they who are the losers"],["أَلَمۡ يَأۡتِهِمۡ نَبَأُ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَقَوۡمِ إِبۡرَٰهِيمَ وَأَصۡحَٰبِ مَدۡيَنَ وَٱلۡمُؤۡتَفِكَٰتِۚ أَتَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ","Hath not the fame of those before them reached them - the folk of Noah, A'ad, Thamud, the folk of Abraham, the dwellers of Midian and the disasters (which befell them)? Their messengers (from Allah) came unto them with proofs (of Allah's Sovereignty). So Allah surely wronged them not, but they did wrong themselves"],["وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَـٰٓئِكَ سَيَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","And the believers, men and women, are protecting friends one of another; they enjoin the right and forbid the wrong, and they establish worship and they pay the poor-due, and they obey Allah and His messenger. As for these, Allah will have mercy on them. Lo! Allah is Mighty, Wise"],["وَعَدَ ٱللَّهُ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّـٰتِ عَدۡنٖۚ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِ أَكۡبَرُۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","Allah promiseth to the believers, men and women, Gardens underneath which rivers flow, wherein they will abide - blessed dwellings in Gardens of Eden. And - greater (far)! - acceptance from Allah. That is the supreme triumph"],["يَـٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ","O Prophet! Strive against the disbelievers and the hypocrites! Be harsh with them. Their ultimate abode is hell, a hapless journey's end"],["يَحۡلِفُونَ بِٱللَّهِ مَا قَالُواْ وَلَقَدۡ قَالُواْ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُواْ بَعۡدَ إِسۡلَٰمِهِمۡ وَهَمُّواْ بِمَا لَمۡ يَنَالُواْۚ وَمَا نَقَمُوٓاْ إِلَّآ أَنۡ أَغۡنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضۡلِهِۦۚ فَإِن يَتُوبُواْ يَكُ خَيۡرٗا لَّهُمۡۖ وَإِن يَتَوَلَّوۡاْ يُعَذِّبۡهُمُ ٱللَّهُ عَذَابًا أَلِيمٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَمَا لَهُمۡ فِي ٱلۡأَرۡضِ مِن وَلِيّٖ وَلَا نَصِيرٖ","They swear by Allah that they said nothing (wrong), yet they did say the word of disbelief, and did disbelieve after their Surrender (to Allah). And they purposed that which they could not attain, and they sought revenge only that Allah by His messenger should enrich them of His bounty. If they repent it will be better for them; and if they turn away, Allah will afflict them with a painful doom in the world and the Hereafter, and they have no protecting friend nor helper in the earth"],["۞وَمِنۡهُم مَّنۡ عَٰهَدَ ٱللَّهَ لَئِنۡ ءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّـٰلِحِينَ","And of them is he who made a covenant with Allah (saying): If He give us of His bounty we will give alms and become of the righteous"],["فَلَمَّآ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُواْ بِهِۦ وَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ","Yet when He gave them of His bounty, they hoarded it and turned away, averse"],["فَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكۡذِبُونَ","So He hath made the consequence (to be) hypocrisy in their hearts until the day when they shall meet Him, because they broke their word to Allah that they promised Him, and because they lied"],["أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ سِرَّهُمۡ وَنَجۡوَىٰهُمۡ وَأَنَّ ٱللَّهَ عَلَّـٰمُ ٱلۡغُيُوبِ","Know they not that Allah knoweth both their secret and the thought that they confide, and that Allah is the Knower of Things Hidden"],["ٱلَّذِينَ يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ مِنَ ٱلۡمُؤۡمِنِينَ فِي ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ","Those who point at such of the believers as give the alms willingly and such as can find naught to give but their endeavours, and deride them - Allah (Himself) derideth them. Theirs will be a painful doom"],["ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ إِن تَسۡتَغۡفِرۡ لَهُمۡ سَبۡعِينَ مَرَّةٗ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ ذَٰلِكَ بِأَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ","Ask forgiveness for them (O Muhammad), or ask not forgiveness for them; though thou ask forgiveness for them seventy times Allah will not forgive them. That is because they disbelieved in Allah and His messenger, and Allah guideth not wrongdoing folk"],["فَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓاْ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَقَالُواْ لَا تَنفِرُواْ فِي ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرّٗاۚ لَّوۡ كَانُواْ يَفۡقَهُونَ","Those who were left behind rejoiced at sitting still behind the messenger of Allah, and were averse to striving with their wealth and their lives in Allah's way. And they said: Go not forth in the heat! Say: The fire of hell is more intense of heat, if they but understood"],["فَلۡيَضۡحَكُواْ قَلِيلٗا وَلۡيَبۡكُواْ كَثِيرٗا جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ","Then let them laugh a little: they will weep much, as the reward of what they used to earn"],["فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٖ مِّنۡهُمۡ فَٱسۡتَـٔۡذَنُوكَ لِلۡخُرُوجِ فَقُل لَّن تَخۡرُجُواْ مَعِيَ أَبَدٗا وَلَن تُقَٰتِلُواْ مَعِيَ عَدُوًّاۖ إِنَّكُمۡ رَضِيتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةٖ فَٱقۡعُدُواْ مَعَ ٱلۡخَٰلِفِينَ","If Allah bring thee back (from the campaign) unto a party of them and they ask of thee leave to go out (to fight), then say unto them: Ye shall never more go out with me nor fight with me against a foe. Ye were content with sitting still the first time. So sit still, with the useless"],["وَلَا تُصَلِّ عَلَىٰٓ أَحَدٖ مِّنۡهُم مَّاتَ أَبَدٗا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓۖ إِنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُواْ وَهُمۡ فَٰسِقُونَ","And never (O Muhammad) pray for one of them who dieth, nor stand by his grave. Lo! they disbelieved in Allah and His messenger, and they died while they were evil-doers"],["وَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَأَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِي ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ","Let not their wealth nor their children please thee! Allah purposeth only to punish them thereby in the world, and that their souls shall pass away while they are disbelievers"],["وَإِذَآ أُنزِلَتۡ سُورَةٌ أَنۡ ءَامِنُواْ بِٱللَّهِ وَجَٰهِدُواْ مَعَ رَسُولِهِ ٱسۡتَـٔۡذَنَكَ أُوْلُواْ ٱلطَّوۡلِ مِنۡهُمۡ وَقَالُواْ ذَرۡنَا نَكُن مَّعَ ٱلۡقَٰعِدِينَ","And when a surah is revealed (which saith): Believe in Allah and strive along with His messenger, the men of wealth among them still ask leave of thee and say: Suffer us to be with those who sit (at home)"],["رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ","They are content that they should be with the useless and their hearts are sealed, so that they apprehend not"],["لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ جَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ وَأُوْلَـٰٓئِكَ لَهُمُ ٱلۡخَيۡرَٰتُۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","But the messenger and those who believe with him strive with their wealth and their lives. Such are they for whom are the good things. Such are they who are the successful"],["أَعَدَّ ٱللَّهُ لَهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","Allah hath made ready for them Gardens underneath which rivers flow, wherein they will abide. That is the supreme triumph"],["وَجَآءَ ٱلۡمُعَذِّرُونَ مِنَ ٱلۡأَعۡرَابِ لِيُؤۡذَنَ لَهُمۡ وَقَعَدَ ٱلَّذِينَ كَذَبُواْ ٱللَّهَ وَرَسُولَهُۥۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٞ","And those among the wandering Arabs who had an excuse came in order that permission might be granted them. And those who lied to Allah and His messenger sat at home. A painful doom will fall on those of them who disbelieve"],["لَّيۡسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ مَا عَلَى ٱلۡمُحۡسِنِينَ مِن سَبِيلٖۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","Not unto the weak nor unto the sick nor unto those who can find naught to spend is any fault (to be imputed though they stay at home) if they are true to Allah and His messenger. Not unto the good is there any road (of blame). Allah is Forgiving, Merciful"],["وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَآ أَجِدُ مَآ أَحۡمِلُكُمۡ عَلَيۡهِ تَوَلَّواْ وَّأَعۡيُنُهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا يَجِدُواْ مَا يُنفِقُونَ","Nor unto those whom, when they came to thee (asking) that thou shouldst mount them, thou didst tell: I cannot find whereon to mount you. They turned back with eyes flowing with tears, for sorrow that they could not find the means to spend"],["۞إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِيَآءُۚ رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَعۡلَمُونَ","The road (of blame) is only against those who ask for leave of thee (to stay at home) when they are rich. They are content to be with the useless. Allah hath sealed their hearts so that they know not"],["يَعۡتَذِرُونَ إِلَيۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَيۡهِمۡۚ قُل لَّا تَعۡتَذِرُواْ لَن نُّؤۡمِنَ لَكُمۡ قَدۡ نَبَّأَنَا ٱللَّهُ مِنۡ أَخۡبَارِكُمۡۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","They will make excuse to you (Muslims) when ye return unto them. Say: Make no excuse, for we shall not believe you. Allah hath told us tidings of you. Allah and His messenger will see your conduct, and then ye will be brought back unto Him Who knoweth the Invisible as well as the Visible, and He will tell you what ye used to do"],["سَيَحۡلِفُونَ بِٱللَّهِ لَكُمۡ إِذَا ٱنقَلَبۡتُمۡ إِلَيۡهِمۡ لِتُعۡرِضُواْ عَنۡهُمۡۖ فَأَعۡرِضُواْ عَنۡهُمۡۖ إِنَّهُمۡ رِجۡسٞۖ وَمَأۡوَىٰهُمۡ جَهَنَّمُ جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ","They will swear by Allah unto you, when ye return unto them, that ye may let them be. Let them be, for lo! they are unclean, and their abode is hell as the reward for what they used to earn"],["يَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡاْ عَنۡهُمۡۖ فَإِن تَرۡضَوۡاْ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا يَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ","They swear unto you, that ye may accept them. Though ye accept them. Allah verily accepteth not wrongdoing folk"],["ٱلۡأَعۡرَابُ أَشَدُّ كُفۡرٗا وَنِفَاقٗا وَأَجۡدَرُ أَلَّا يَعۡلَمُواْ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","The wandering Arabs are more hard in disbelief and hypocrisy, and more likely to be ignorant of the limits which Allah hath revealed unto His messenger. And Allah is Knower, Wise"],["وَمِنَ ٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمٗا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ","And of the wandering Arabs there is he who taketh that which he expendeth (for the cause of Allah) as a loss, and awaiteth (evil) turns of fortune for you (that he may be rid of it). The evil turn of fortune will be theirs. Allah is Hearer, Knower"],["وَمِنَ ٱلۡأَعۡرَابِ مَن يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِۚ أَلَآ إِنَّهَا قُرۡبَةٞ لَّهُمۡۚ سَيُدۡخِلُهُمُ ٱللَّهُ فِي رَحۡمَتِهِۦٓۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","And of the wandering Arabs there is he who believeth in Allah and the Last Day, and taketh that which he expendeth and also the prayers of the messenger as acceptable offerings in the sight of Allah. Lo! verily it is an acceptable offering for them. Allah will bring them into His mercy. Lo! Allah is Forgiving, Merciful"],["وَٱلسَّـٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحۡسَٰنٖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ وَأَعَدَّ لَهُمۡ جَنَّـٰتٖ تَجۡرِي تَحۡتَهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","And the first to lead the way, of the Muhajirin and the Ansar, and those who followed them in goodness - Allah is well pleased with them and they are well pleased with Him, and He hath made ready for them Gardens underneath which rivers flow, wherein they will abide for ever. That is the supreme triumph"],["وَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ مُنَٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِينَةِ مَرَدُواْ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَيۡنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٖ","And among those around you of the wandering Arabs there are hypocrites, and among the townspeople of Al-Madinah (there are some who) persist in hypocrisy whom thou (O Muhammad) knowest not. We, We know them, and We shall chastise them twice; then they will be relegated to a painful doom"],["وَءَاخَرُونَ ٱعۡتَرَفُواْ بِذُنُوبِهِمۡ خَلَطُواْ عَمَلٗا صَٰلِحٗا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","And (there are) others who have acknowledged their faults. They mixed a righteous action with another that was bad. It may be that Allah will relent toward them. Lo! Allah is Forgiving, Merciful"],["خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","Take alms of their wealth, wherewith thou mayst purify them and mayst make them grow, and pray for them. Lo! thy prayer is an assuagement for them. Allah is Hearer, Knower"],["أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ هُوَ يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَأۡخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","Know they not that Allah is He Who accepteth repentance from His bondmen and taketh the alms, and that Allah is He Who is the Relenting, the Merciful"],["وَقُلِ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","And say (unto them): Act! Allah will behold your actions, and (so will) His messenger and the believers, and ye will be brought back to the Knower of the Invisible and the Visible, and He will tell you what ye used to do"],["وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمۡ وَإِمَّا يَتُوبُ عَلَيۡهِمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","And (there are) others who await Allah's decree, whether He will punish them or will forgive them. Allah is Knower, Wise"],["وَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدٗا ضِرَارٗا وَكُفۡرٗا وَتَفۡرِيقَۢا بَيۡنَ ٱلۡمُؤۡمِنِينَ وَإِرۡصَادٗا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ وَلَيَحۡلِفُنَّ إِنۡ أَرَدۡنَآ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ","And as for those who chose a place of worship out of opposition and disbelief, and in order to cause dissent among the believers, and as an outpost for those who warred against Allah and His messenger aforetime, they will surely swear: We purposed naught save good. Allah beareth witness that they verily are liars"],["لَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ","Never stand (to pray) there. A place of worship which was found upon duty (to Allah) from the first day is more worthy that thou shouldst stand (to pray) therein, wherein are men who love to purify themselves. Allah loveth the purifiers"],["أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ أَم مَّنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٖ فَٱنۡهَارَ بِهِۦ فِي نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ","Is he who founded his building upon duty to Allah and His good pleasure better; or he who founded his building on the brink of a crumbling, overhanging precipice so that it toppled with him into the fire of hell? Allah guideth not wrongdoing folk"],["لَا يَزَالُ بُنۡيَٰنُهُمُ ٱلَّذِي بَنَوۡاْ رِيبَةٗ فِي قُلُوبِهِمۡ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ","The building which they built will never cease to be a misgiving in their hearts unless their hearts be torn to pieces. Allah is Knower, Wise"],["۞إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ وَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقّٗا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ بِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","Lo! Allah hath bought from the believers their lives and their wealth because the Garden will be theirs: they shall fight in the way of Allah and shall slay and be slain. It is a promise which is binding on Him in the Torah and the Gospel and the Qur'an. Who fulfilleth His covenant better than Allah? Rejoice then in your bargain that ye have made, for that is the supreme triumph"],["ٱلتَّـٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّـٰٓئِحُونَ ٱلرَّـٰكِعُونَ ٱلسَّـٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ","(Triumphant) are those who turn repentant (to Allah), those who serve (Him), those who praise (Him), those who fast, those who bow down, those who fall prostrate (in worship), those who enjoin the right and who forbid the wrong and those who keep the limits (ordained) of Allah - And give glad tidings to believers"],["مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ","It is not for the Prophet, and those who believe, to pray for the forgiveness of idolaters even though they may be near of kin (to them) after it hath become clear that they are people of hell-fire"],["وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةٖ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوّٞ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَٰهِيمَ لَأَوَّـٰهٌ حَلِيمٞ","The prayer of Abraham for the forgiveness of his father was only because of a promise he had promised him, but when it had become clear unto him that he (his father) was an enemy to Allah he (Abraham) disowned him. Lo! Abraham was soft of heart, long-suffering"],["وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ","It was never Allah's (part) that He should send a folk astray after He had guided them until He had made clear unto them what they should avoid. Lo! Allah is Aware of all things"],["إِنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ","Lo! Allah! Unto Him belongeth the Sovereignty of the heavens and the earth. He quickeneth and He giveth death. And ye have, instead of Allah, no protecting friend nor helper"],["لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٖ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفٞ رَّحِيمٞ","Allah hath turned in mercy to the Prophet, and to the Muhajirin and the Ansar who followed him in the hour of hardship. After the hearts of a party of them had almost swerved aside, then turned He unto them in mercy. Lo! He is Full of Pity, Merciful for them"],["وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","And to the three also (did He turn in mercy) who were left behind, when the earth, vast as it is, was straitened for them, and their own souls were straitened for them till they bethought them that there is no refuge from Allah save toward Him. Then turned He unto them in mercy that they (too) might turn (repentant unto Him). Lo! Allah! He is the Relenting, the Merciful"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ ٱلصَّـٰدِقِينَ","O ye who believe! Be careful of your duty to Allah, and be with the truthful"],["مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ وَمَنۡ حَوۡلَهُم مِّنَ ٱلۡأَعۡرَابِ أَن يَتَخَلَّفُواْ عَن رَّسُولِ ٱللَّهِ وَلَا يَرۡغَبُواْ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأٞ وَلَا نَصَبٞ وَلَا مَخۡمَصَةٞ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئٗا يَغِيظُ ٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوّٖ نَّيۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٞ صَٰلِحٌۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ","It is not for the townsfolk of Al-Madinah and for those around them of the wandering Arabs so stay behind the messenger of Allah and prefer their lives to his life. That is because neither thirst nor toil nor hunger afflicteth them in the way of Allah, nor step they any step that angereth the disbelievers, nor gain they from the enemy a gain, but a good deed is recorded for them therefor. Lo! Allah loseth not the wages of the good"],["وَلَا يُنفِقُونَ نَفَقَةٗ صَغِيرَةٗ وَلَا كَبِيرَةٗ وَلَا يَقۡطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمۡ لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا كَانُواْ يَعۡمَلُونَ","Nor spend they any spending, small or great, nor do they cross a valley, but it is recorded for them, that Allah may repay them the best of what they used to do"],["۞وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ","And the believers should not all go out to fight. Of every troop of them, a party only should go forth, that they (who are left behind) may gain sound knowledge in religion, and that they may warn their folk when they return to them, so that they may beware"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ","O ye who believe! Fight those of the disbelievers who are near to you, and let them find harshness in you, and know that Allah is with those who keep their duty (unto Him)"],["وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ فَمِنۡهُم مَّن يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ إِيمَٰنٗاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنٗا وَهُمۡ يَسۡتَبۡشِرُونَ","And whenever a surah is revealed there are some of them who say: Which one of you hath thus increased in faith? As for those who believe, it hath increased them in faith and they rejoice (therefor)"],["وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ وَمَاتُواْ وَهُمۡ كَٰفِرُونَ","But as for those in whose hearts is disease, it only addeth wickedness to their wickedness, and they die while they are disbelievers"],["أَوَلَا يَرَوۡنَ أَنَّهُمۡ يُفۡتَنُونَ فِي كُلِّ عَامٖ مَّرَّةً أَوۡ مَرَّتَيۡنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمۡ يَذَّكَّرُونَ","See they not that they are tested once or twice in every year? Still they turn not in repentance, neither pay they heed"],["وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ يَرَىٰكُم مِّنۡ أَحَدٖ ثُمَّ ٱنصَرَفُواْۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ","And whenever a surah is revealed, they look one at another (as who should say): Doth anybody see you? Then they turn away. Allah turneth away their hearts because they are a folk who understand not"],["لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ رَءُوفٞ رَّحِيمٞ","There hath come unto you a messenger, (one) of yourselves, unto whom aught that ye are overburdened is grievous, full of concern for you, for the believers full of pity, merciful"],["فَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ","Now, if they turn away (O Muhammad) say: Allah sufficeth me. There is no Allah save Him. In Him have I put my trust, and He is Lord of the Tremendous Throne"]],"jal":[[1,1,"سُورَة التَّوْبَة [ مَدَنِيَّة إلّا الآيَتَيْنِ الأَخِيرَتَيْنِ فَمَكِّيَّتانِ وآياتها ١٢٩ نَزَلَتْ بَعْد المائِدَة ] ولَمْ تُكْتَب فِيها البَسْمَلَة لِأَنَّهُ ﷺ لَمْ يَأْمُر بِذَلِكَ كَما يُؤْخَذ مِن حَدِيث رَواهُ الحاكِم وأَخْرَجَ فِي مَعْناهُ عَنْ عَلِيّ أنَّ البَسْمَلَة أمان وهِيَ نَزَلَتْ لِرَفْعِ الأَمْن بِالسَّيْفِ وعَنْ حُذَيْفَة (إنّكُمْ تُسَمُّونَها سُورَة التَّوْبَة وهِيَ سُورَة العَذاب ورَوى البُخارِيّ عَنْ البَراء أنَّها آخِر سُورَة نَزَلَتْ.\n\nهَذِهِ ﴿بَراءَة مِن اللَّه ورَسُوله﴾ واصِلَة ﴿إلى الَّذِينَ عاهَدْتُمْ مِن المُشْرِكِينَ﴾ عَهْدًا مُطْلَقًا أوْ دُون أرْبَعَة أشْهُر أوْ فَوْقها ونَصّ العَهْد بِما يُذْكَر فِي قَوْله:"],[2,2,"﴿فَسِيحُوا﴾ سِيرُوا آمِنِينَ أيّها المُشْرِكُونَ ﴿فِي الأَرْض أرْبَعَة أشْهُر﴾ أوَّلها شَوّال بِدَلِيلِ ما سَيَأْتِي ولا أمان لَكُمْ بَعْدها ﴿واعْلَمُوا أنَّكُمْ غَيْر مُعْجِزِي اللَّه﴾ أيْ فائِتِي عَذابه ﴿وأَنَّ اللَّه مُخْزِي الكافِرِينَ﴾ مُذِلّهمْ فِي الدُّنْيا بِالقَتْلِ والأُخْرى بِالنّارِ"],[3,3,"﴿وأَذان﴾ إعْلام ﴿مِن اللَّه ورَسُوله إلى النّاس يَوْم الحَجّ الأَكْبَر﴾ يَوْم النَّحْر ﴿أنَّ﴾ أيْ بِأَنَّ ﴿اللَّه بَرِيء مِن المُشْرِكِينَ﴾ وعُهُودهمْ ﴿ورَسُوله﴾ بَرِيء أيْضًا \"وقَدْ بَعَثَ النَّبِيّ ﷺ عَلِيًّا مِن السَّنَة وهِيَ سَنَة تِسْع فَأَذَّنَ يَوْم النَّحْر بِمِنًى بِهَذِهِ الآيات وأَنْ لا يَحُجّ بَعْد العام مُشْرِك ولا يَطُوف بِالبَيْتِ عُرْيان. رَواهُ البُخارِيّ ﴿فَإنْ تُبْتُمْ﴾ مِن الكُفْر ﴿فَهُوَ خَيْر لَكُمْ وإنْ تَوَلَّيْتُمْ﴾ عَنْ الإيمان ﴿فاعْلَمُوا أنَّكُمْ غَيْر مُعْجِزِي اللَّه وبَشِّرْ﴾ أخْبِرْ ﴿الَّذِينَ كَفَرُوا بِعَذابٍ ألِيم﴾ مُؤْلِم وهُوَ القَتْل والأَسْر فِي الدُّنْيا والنّار فِي الآخِرَة"],[4,4,"﴿إلّا الَّذِينَ عاهَدْتُمْ مِن المُشْرِكِينَ ثُمَّ لَمْ يَنْقُصُوكُمْ شَيْئًا﴾ مِن شُرُوط العَهْد ﴿ولَمْ يُظاهِرُوا﴾ يُعاوِنُوا ﴿عَلَيْكُمْ أحَدًا﴾ مِن الكُفّار ﴿فَأَتِمُّوا إلَيْهِمْ عَهْدهمْ إلى﴾ انْقِضاء ﴿مُدَّتهمْ﴾ الَّتِي عاهَدْتُمْ عَلَيْها ﴿إنّ اللَّه يُحِبّ المُتَّقِينَ﴾ بِإتْمامِ العُهُود"],[5,5,"﴿فَإذا انْسَلَخَ﴾ خَرَجَ ﴿الأَشْهُر الحُرُم﴾ وهِيَ آخِر مُدَّة التَّأْجِيل ﴿فاقْتُلُوا المُشْرِكِينَ حَيْثُ وجَدْتُمُوهُمْ﴾ فِي حِلّ أوْ حَرَم ﴿وخُذُوهُمْ﴾ بِالأَسْرِ ﴿واحْصُرُوهُمْ﴾ فِي القِلاع والحُصُون حَتّى يُضْطَرُّوا إلى القَتْل أوْ الإسْلام ﴿واقْعُدُوا لَهُمْ كُلّ مَرْصَد﴾ طَرِيق يَسْلُكُونَهُ ونُصِبَ كُلّ عَلى نَزْع الخافِض ﴿فَإنْ تابُوا﴾ مِن الكُفْر ﴿وأَقامُوا الصَّلاة وآتَوْا الزَّكاة فَخَلُّوا سَبِيلهمْ﴾ ولا تَتَعَرَّضُوا لَهُمْ ﴿إنّ اللَّه غَفُور رَحِيم﴾ لِمَن تابَ"],[6,6,"﴿وإنْ أحَد مِن المُشْرِكِينَ﴾ مَرْفُوع بِفِعْلٍ يُفَسِّرهُ ﴿اسْتَجارَك﴾ اسْتَأْمَنَك مِن القَتْل ﴿فَأَجِرْهُ﴾ أمِّنْهُ ﴿حَتّى يَسْمَع كَلام اللَّه﴾ القُرْآن ﴿ثُمَّ أبْلِغْهُ مَأْمَنه﴾ وهُوَ دار قَوْمه إنْ لَمْ يُؤْمِن لِيَنْظُر فِي أمْره ﴿ذَلِكَ﴾ المَذْكُور ﴿بِأَنَّهُمْ قَوْم لا يَعْلَمُونَ﴾ دِين اللَّه فَلا بُدّ لَهُمْ مِن سَماع القُرْآن لِيَعْلَمُوا"],[7,7,"﴿كَيْفَ﴾ أيْ لا ﴿يَكُون لِلْمُشْرِكِينَ عَهْد عِنْد اللَّه وعِنْد رَسُوله﴾ وهُمْ كافِرُونَ بِاللَّهِ ورَسُوله غادِرُونَ ﴿إلّا الَّذِينَ عاهَدْتُمْ عِنْد المَسْجِد الحَرام﴾ يَوْم الحُدَيْبِيَة وهُمْ قُرَيْش المُسْتَثْنَوْنَ مِن قَبْل ﴿فَما اسْتَقامُوا لَكُمْ﴾ أقامُوا عَلى العَهْد ولَمْ يَنْقُضُوهُ وما شَرْطِيَّة ﴿فاسْتَقِيمُوا لَهُمْ إنّ اللَّه يُحِبّ المُتَّقِينَ﴾ عَلى الوَفاء بِهِ وقَدْ اسْتَقامَ النَّبِيّ ﷺ عَلى عَهْدهمْ حَتّى نَقَضُوا بِإعانَةِ بَنِي بَكْر عَلى خُزاعَة"],[8,8,"﴿كَيْفَ﴾ يَكُون لَهُمْ عَهْد ﴿وإنْ يَظْهَرُوا عَلَيْكُمْ﴾ يَظْفَرُوا بِكُمْ وجُمْلَة الشَّرْط حال ﴿لا يَرْقُبُوا﴾ يُراعُوا ﴿فِيكُمْ إلًّا﴾ قَرابَة ﴿ولا ذِمَّة﴾ عَهْدًا بَلْ يُؤْذُوكُمْ ما اسْتَطاعُوا ﴿يُرْضُونَكُمْ بِأَفْواهِهِمْ﴾ بِكَلامِهِمْ الحَسَن ﴿وتَأْبى قُلُوبهمْ﴾ الوَفاء بِهِ ﴿وأَكْثَرهمْ فاسِقُونَ﴾ ناقِضُونِ لِلْعَهْدِ"],[9,9,"﴿اشْتَرَوْا بِآياتِ اللَّه﴾ القُرْآن ﴿ثَمَنًا قَلِيلًا﴾ مِن الدُّنْيا أيْ تَرَكُوا اتِّباعها لِلشَّهَواتِ والهَوى ﴿فَصَدُّوا عَنْ سَبِيله﴾ دِينه ﴿إنّهُمْ ساءَ﴾ بِئْسَ ﴿ما كانُوا يَعْمَلُونَـ﴾ ـهُ عَمَلهمْ هَذا"],[11,11,"﴿فَإنْ تابُوا وأَقامُوا الصَّلاة وآتَوْا الزَّكاة فَإخْوانكُمْ﴾ أيْ فَهُمْ إخْوانكُمْ ﴿فِي الدِّين ونُفَصِّل﴾ نُبَيِّن ﴿الآيات لِقَوْمٍ يَعْلَمُونَ﴾ يَتَدَبَّرُونَ"],[12,12,"﴿وإنْ نَكَثُوا﴾ نَقَضُوا ﴿أيْمانهمْ﴾ مَواثِيقهمْ ﴿مِن بَعْد عَهْدهمْ وطَعَنُوا فِي دِينكُمْ﴾ عابُوهُ ﴿فَقاتِلُوا أئِمَّة الكُفْر﴾ رُؤَساءَهُ فِيهِ وضْع الظّاهِر مَوْضِع المُضْمَر ﴿إنّهُمْ لا أيْمان﴾ عُهُود ﴿لَهُمْ﴾ وفِي قِراءَة بِالكَسْرِ ﴿لَعَلَّهُمْ يَنْتَهُونَ﴾ عَنْ الكُفْر"],[13,13,"﴿ألا﴾ لِلتَّحْضِيضِ ﴿تُقاتِلُونَ قَوْمًا نَكَثُوا﴾ نَقَضُوا ﴿أيْمانهمْ﴾ عُهُودهمْ ﴿وهَمُّوا بِإخْراجِ الرَّسُول﴾ مِن مَكَّة لَمّا تَشاوَرُوا فِيهِ بِدارِ النَّدْوَة ﴿وهُمْ بَدَءُوكُمْ﴾ بِالقِتالِ ﴿أوَّل مَرَّة﴾ حَيْثُ قاتَلُوا خُزاعَة حُلَفاءَكُمْ مَعَ بَنِي بَكْر فَما يَمْنَعكُمْ أنْ تُقاتِلُوهُمْ ﴿أتَخْشَوْنَهُمْ﴾ أتَخافُونَهُمْ ﴿فاللَّه أحَقّ أنْ تَخْشَوْهُ﴾ فِي تَرْك قِتالهمْ"],[14,14,"﴿قاتِلُوهُمْ يُعَذِّبهُمْ اللَّه﴾ يَقْتُلهُمْ ﴿بِأَيْدِيكُمْ ويُخْزِهِمْ﴾ يُذِلّهُمْ بِالأَسْرِ والقَهْر ﴿ويَنْصُركُمْ عَلَيْهِمْ ويَشْفِ صُدُور قَوْم مُؤْمِنِينَ﴾ بِما فَعَلَ بِهِمْ هُمْ بَنُو خُزاعَة"],[15,15,"﴿ويُذْهِب غَيْظ قُلُوبهمْ﴾ كَرْبها ﴿ويَتُوب اللَّه عَلى مَن يَشاء﴾ بِالرُّجُوعِ إلى الإسْلام كَأَبِي سُفْيان"],[16,16,"﴿أمْ﴾ بِمَعْنى هَمْزَة الإنْكار ﴿حَسِبْتُمْ أنْ تُتْرَكُوا ولَمّا﴾ لَمْ ﴿يَعْلَم اللَّه﴾ عِلْم ظُهُور ﴿الَّذِينَ جاهَدُوا مِنكُمْ﴾ بِإخْلاصٍ ﴿ولَمْ يَتَّخِذُوا مِن دُون اللَّه ولا رَسُوله ولا المُؤْمِنِينَ ولِيجَة﴾ بِطانَة وأَوْلِياء المَعْنى ولَمْ يَظْهَر المُخْلِصُونَ وهُمْ المَوْصُوفُونَ بِما ذُكِرَ مِن غَيْرهمْ"],[17,17,"﴿ما كانَ لِلْمُشْرِكِينَ أنْ يَعْمُرُوا مَساجِد اللَّه﴾ بِالإفْرادِ والجَمْع بِدُخُولِهِ والقُعُود فِيهِ ﴿شاهِدِينَ عَلى أنْفُسهمْ بِالكُفْرِ أُولَئِكَ حَبِطَتْ﴾ بَطَلَتْ ﴿أعْمالهمْ﴾ لِعَدَمِ شَرْطها"],[18,18,"﴿إنّما يَعْمُر مَساجِد اللَّه مَن آمَنَ بِاللَّهِ واليَوْم الآخِر وأَقامَ الصَّلاة وآتى الزَّكاة ولَمْ يَخْشَ﴾ أحَدًا"],[19,19,"﴿أجَعَلْتُمْ سِقايَة الحاجّ وعِمارَة المَسْجِد الحَرام﴾ أيْ أهْل ذَلِكَ ﴿كَمَن آمَنَ بِاللَّهِ واليَوْم الآخِر وجاهَدَ فِي سَبِيل اللَّه لا يَسْتَوُونَ عِنْد اللَّه﴾ فِي الفَضْل ﴿واللَّه لا يَهْدِي القَوْم الظّالِمِينَ﴾ الكافِرِينَ نَزَلَتْ رَدًّا عَلى مَن قالَ ذَلِكَ وهُوَ العَبّاس أوْ غَيْره"],[20,20,"﴿الَّذِينَ آمَنُوا وهاجَرُوا وجاهَدُوا فِي سَبِيل اللَّه بِأَمْوالِهِمْ وأَنْفُسهمْ أعْظَم دَرَجَة﴾ رُتْبَة ﴿عِنْد اللَّه﴾ مِن غَيْرهمْ ﴿وأُولَئِكَ هُمْ الفائِزُونَ﴾ الظّافِرُونَ بِالخَيْرِ"],[21,21,"﴿يُبَشِّرهُمْ رَبّهمْ بِرَحْمَةٍ مِنهُ ورِضْوان وجَنّات لَهُمْ فِيها نَعِيم مُقِيم﴾ دائِم"],[22,22,"﴿خالِدِينَ﴾ حال مُقَدَّرَة"],[23,23,"ونَزَلَ فِيمَن تَرَكَ الهِجْرَة لِأَجْلِ أهْله وتِجارَته ﴿يا أيّها الَّذِينَ آمَنُوا لا تَتَّخِذُوا آباءَكُمْ وإخْوانكُمْ أوْلِياء إنْ اسْتَحَبُّوا﴾ اخْتارُوا"],[24,24,"﴿قُلْ إنْ كانَ آباؤُكُمْ وأَبْناؤُكُمْ وإخْوانكُمْ وأَزْواجكُمْ وعَشِيرَتكُمْ﴾ أقْرِباؤُكُمْ وفِي قِراءَة عَشِيراتكُمْ ﴿وأَمْوال اقْتَرَفْتُمُوها﴾ اكْتَسَبْتُمُوها ﴿وتِجارَة تَخْشَوْنَ كَسادها﴾ عَدَم نَفادها ﴿ومَساكِن تَرْضَوْنَها أحَبّ إلَيْكُمْ مِن اللَّه ورَسُوله وجِهاد فِي سَبِيله﴾ فَقَعَدْتُمْ لِأَجْلِهِ عَنْ الهِجْرَة والجِهاد ﴿فَتَرَبَّصُوا﴾ انْتَظِرُوا ﴿حَتّى يَأْتِيَ اللَّه بِأَمْرِهِ﴾ تَهْدِيد لَهُمْ"],[25,25,"﴿لَقَدْ نَصَرَكُمْ اللَّه فِي مَواطِن﴾ لِلْحَرْبِ ﴿كَثِيرَة﴾ كَبَدْرٍ وقُرَيْظَة والنَّضِير ﴿و﴾ اُذْكُرْ ﴿يَوْم حُنَيْن﴾ وادٍ بَيْن مَكَّة والطّائِف أيْ يَوْم قِتالكُمْ فِيهِ هَوازِن وذَلِك فِي شَوّال سَنَة ثَمان ﴿إذْ﴾ بَدَل مِن يَوْم ﴿أعْجَبَتْكُمْ كَثْرَتكُمْ﴾ فَقُلْتُمْ لَنْ نُغْلَب اليَوْم مِن قِلَّة وكانُوا اثْنَيْ عَشَرَ ألْفًا والكُفّار أرْبَعَة آلاف ﴿فَلَمْ تُغْنِ عَنْكُمْ شَيْئًا وضاقَتْ عَلَيْكُمْ الأَرْض بِما رَحُبَتْ﴾ ما مَصْدَرِيَّة أيْ مَعَ رَحْبها أيْ سِعَتها فَلَمْ تَجِدُوا مَكانًا تَطْمَئِنُّونَ إلَيْهِ لِشِدَّةِ ما لَحِقَكُمْ مِن الخَوْف ﴿ثُمَّ ولَّيْتُمْ مُدْبِرِينَ﴾ مُنْهَزِمِينَ وثَبَتَ النَّبِيّ ﷺ عَلى بَغْلَته البَيْضاء ولَيْسَ مَعَهُ غَيْر العَبّاس وأَبُو سُفْيان آخِذ بِرِكابِهِ"],[26,26,"﴿ثُمَّ أنْزَلَ اللَّه سَكِينَته﴾ طُمَأْنِينَته ﴿عَلى رَسُوله وعَلى المُؤْمِنِينَ﴾ فَرَدُّوا إلى النَّبِيّ ﷺ لَمّا ناداهُمْ العَبّاس بِإذْنِهِ وقاتَلُوا ﴿وأَنْزَلَ جُنُودًا لَمْ تَرَوْها﴾ مَلائِكَة ﴿وعَذَّبَ الَّذِينَ كَفَرُوا﴾ بِالقَتْلِ والأَسْر"],[27,27,"﴿ثُمَّ يَتُوب اللَّه مِن بَعْد ذَلِكَ عَلى مَن يَشاء﴾ مِنهُمْ بِالإسْلامِ"],[28,28,"﴿يا أيّها الَّذِينَ آمَنُوا إنّما المُشْرِكُونَ نَجَس﴾ قَذَر لِخُبْثِ باطِنهمْ ﴿فَلا يَقْرَبُوا المَسْجِد الحَرام﴾ أيْ لا يَدْخُلُوا الحَرَم ﴿بَعْد عامهمْ هَذا﴾ عام تِسْع مِن الهِجْرَة ﴿وإنْ خِفْتُمْ عَيْلَة﴾ فَقْرًا بِانْقِطاعِ تِجارَتهمْ عَنْكُمْ ﴿فَسَوْفَ يُغْنِيكُمْ اللَّه مِن فَضْله إنْ شاءَ﴾ وقَدْ أغْناهُمْ بِالفُتُوحِ والجِزْيَة"],[29,29,"﴿قاتِلُوا الَّذِينَ لا يُؤْمِنُونَ بِاللَّهِ ولا بِاليَوْمِ الآخِر﴾ وإلّا لَآمَنُوا بِالنَّبِيِّ ﷺ ﴿ولا يُحَرِّمُونَ ما حَرَّمَ اللَّه ورَسُوله﴾ كالخَمْرِ ﴿ولا يَدِينُونَ دِين الحَقّ﴾ الثّابِت النّاسِخ لِغَيْرِهِ مِن الأَدْيان وهُوَ دِين الإسْلام ﴿مِن﴾ بَيان لِلَّذِينَ ﴿الَّذِينَ أُوتُوا الكِتاب﴾ أيْ اليَهُود والنَّصارى ﴿حَتّى يُعْطُوا الجِزْيَة﴾ الخَراج المَضْرُوب عَلَيْهِمْ كُلّ عام ﴿عَنْ يَد﴾ حال أيْ مُنْقادِينَ أوْ بِأَيْدِيهِمْ لا يُوَكَّلُونَ بِها ﴿وهُمْ صاغِرُونَ﴾ أذِلّاء مُنْقادُونَ لِحُكْمِ الإسْلام"],[30,30,"﴿وقالَتْ اليَهُود عُزَيْر ابْن اللَّه وقالَتْ النَّصارى المَسِيح﴾ عِيسى ﴿ابْن اللَّه ذَلِكَ قَوْلهمْ بِأَفْواهِهِمْ﴾ لا مُسْتَنِد لَهُمْ عَلَيْهِ بَلْ ﴿يُضاهِئُونَ﴾ يُشابِهُونَ بِهِ ﴿قَوْل الَّذِينَ كَفَرُوا مِن قَبْل﴾ مِن آبائِهِمْ تَقْلِيدًا لَهُمْ ﴿قاتَلَهُمْ﴾ لَعَنَهُمْ ﴿اللَّه أنّى﴾ كَيْفَ ﴿يُؤْفَكُونَ﴾ يُصْرَفُونَ عَنْ الحَقّ مَعَ قِيام الدَّلِيل"],[31,31,"﴿اتَّخَذُوا أحْبارهمْ﴾ عُلَماء اليَهُود ﴿ورُهْبانهمْ﴾ عُبّاد النَّصارى ﴿أرْبابًا مِن دُون اللَّه﴾ حَيْثُ اتَّبَعُوهُمْ فِي تَحْلِيل ما حَرَّمَ اللَّه وتَحْرِيم ما أحَلَّ ﴿والمَسِيح ابْن مَرْيَم وما أُمِرُوا﴾ فِي التَّوْراة والإنْجِيل ﴿إلّا لِيَعْبُدُوا﴾ أيْ بِأَنْ يَعْبُدُوا ﴿إلَهًا واحِدًا لا إلَه إلّا هُوَ سُبْحانه﴾ تَنْزِيهًا لَهُ"],[32,32,"﴿يُرِيدُونَ أنْ يُطْفِئُوا نُور اللَّه﴾ شَرْعه وبَراهِينه ﴿بِأَفْواهِهِمْ﴾ بِأَقْوالِهِمْ فِيهِ ﴿ويَأْبى اللَّه إلّا أنْ يُتِمّ﴾ يُظْهِر ﴿نُوره ولَوْ كَرِهَ الكافِرُونَ﴾ ذَلِكَ"],[33,33,"﴿هُوَ الَّذِي أرْسَلَ رَسُوله﴾ مُحَمَّدًا ﷺ ﴿بِالهُدى ودِين الحَقّ لِيُظْهِرهُ﴾ يُعْلِيه ﴿عَلى الدِّين كُلّه﴾ جَمِيع الأَدْيان المُخالِفَة لَهُ ﴿ولَوْ كَرِهَ المُشْرِكُونَ﴾ ذَلِكَ"],[34,34,"﴿يا أيّها الَّذِينَ آمَنُوا إنّ كَثِيرًا مِن الأَحْبار والرُّهْبان لَيَأْكُلُونَ﴾ يَأْخُذُونَ ﴿أمْوال النّاس بِالباطِلِ﴾ كالرِّشا فِي الحُكْم ﴿ويَصُدُّونَ﴾ النّاس ﴿عَنْ سَبِيل اللَّه﴾ دِينه ﴿والَّذِينَ﴾ مُبْتَدَأ ﴿يَكْنِزُونَ الذَّهَب والفِضَّة ولا يُنْفِقُونَها﴾ أيْ الكُنُوز ﴿فِي سَبِيل اللَّه﴾ أيْ لا يُؤَدُّونَ مِنها حَقّه مِن الزَّكاة والخَبَر ﴿فَبَشِّرْهُمْ﴾ أخْبِرْهُمْ ﴿بِعَذابٍ ألِيم﴾ مُؤْلِم"],[35,35,"﴿يَوْم يُحْمى عَلَيْها فِي نار جَهَنَّم فَتُكْوى﴾ تُحْرَق ﴿بِها جِباههمْ وجُنُوبهمْ وظُهُورهمْ﴾ وتُوَسِّع جُلُودهمْ حَتّى تُوضَع عَلَيْها كُلّها ويُقال لَهُمْ ﴿هَذا ما كَنَزْتُمْ لِأَنْفُسِكُمْ فَذُوقُوا ما كُنْتُمْ تَكْنِزُونَ﴾ أيْ جَزاءَهُ"],[36,36,"﴿إنّ عِدَّة الشُّهُور﴾ المُعْتَدّ بِها لِلسَّنَةِ ﴿عِنْد اللَّه اثْنا عَشَرَ شَهْرًا فِي كِتاب اللَّه﴾ اللَّوْح المَحْفُوظ ﴿يَوْم خَلَقَ السَّماوات والأَرْض مِنها﴾ أيْ الشُّهُور ﴿أرْبَعَة حُرُم﴾ مُحَرَّمَة ذُو القَعْدَة وذُو الحِجَّة والمُحَرَّم ورَجَب ﴿ذَلِكَ﴾ أيْ تَحْرِيمها ﴿الدِّين القَيِّم﴾ المُسْتَقِيم ﴿فَلا تَظْلِمُوا فِيهِنَّ﴾ أيْ الأَشْهُر الحُرُم ﴿أنْفُسكُمْ﴾ بِالمَعاصِي فَإنَّها فِيها أعْظَم وِزْرًا وقِيلَ فِي الأَشْهُر كُلّها ﴿وقاتِلُوا المُشْرِكِينَ كافَّة﴾ جَمِيعًا فِي كُلّ الشُّهُور ﴿كَما يُقاتِلُونَكُمْ كافَّة واعْلَمُوا أنَّ اللَّه مَعَ المُتَّقِينَ﴾ بِالعَوْنِ والنَّصْر"],[37,37,"﴿إنّما النَّسِيء﴾ أيْ التَّأْخِير لِحُرْمَةِ شَهْر إلى آخَر كَما كانَتْ الجاهِلِيَّة تَفْعَلهُ مِن تَأْخِير حُرْمَة المُحَرَّم إذا هَلَّ وهُمْ فِي القِتال إلى صَفَر ﴿زِيادَة فِي الكُفْر﴾ لِكُفْرِهِمْ بِحُكْمِ اللَّه فِيهِ ﴿يُضَلّ﴾ بِضَمِّ الياء وفَتْحها ﴿بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ﴾ أيْ النَّسِيء ﴿عامًا ويُحَرِّمُونَهُ عامًا لِيُواطِئُوا﴾ يُوافِقُوا بِتَحْلِيلِ شَهْر وتَحْرِيم آخَر بَدَله ﴿عِدَّة﴾ عَدَد ﴿ما حَرَّمَ اللَّه﴾ مِن الأَشْهُر فَلا يَزِيدُوا عَلى تَحْرِيم أرْبَعَة ولا يَنْقُصُوا ولا يَنْظُرُوا إلى أعْيانها ﴿فَيُحِلُّوا ما حَرَّمَ اللَّه زُيِّنَ لَهُمْ سُوء أعْمالهمْ﴾ فَظَنُّوهُ حَسَنًا"],[38,38,"ونَزَلَ لَمّا دَعا النَّبِيّ ﷺ النّاس إلى غَزْوَة تَبُوك وكانُوا فِي عُسْرَة وشِدَّة حَرّ فَشَقَّ عَلَيْهِمْ ﴿يا أيّها الَّذِينَ آمَنُوا ما لَكُمْ إذا قِيلَ لَكُمْ انْفِرُوا فِي سَبِيل اللَّه اثّاقَلْتُمْ﴾ بِإدْغامِ التّاء فِي الأَصْل فِي المُثَلَّثَة واجْتِلاب هَمْزَة الوَصْل أيْ تَباطَأْتُمْ ومِلْتُمْ عَنْ الجِهاد ﴿إلى الأَرْض﴾ والقُعُود فِيها ﴿أرَضِيتُمْ بِالحَياةِ الدُّنْيا﴾ ولَذّاتها والِاسْتِفْهام لِلتَّوْبِيخِ ﴿مِن الآخِرَة﴾ أيْ بَدَل نَعِيمها ﴿فَما مَتاع الحَياة الدُّنْيا فِي﴾ جَنْب مَتاع ﴿الآخِرَة إلّا قَلِيل﴾ حَقِير"],[39,39,"﴿إلّا﴾ بِإدْغامِ لا فِي نُون إنْ الشَّرْطِيَّة فِي المَوْضِعَيْنِ ﴿تَنْفِرُوا﴾ تَخْرُجُوا مَعَ النَّبِيّ ﷺ لِلْجِهادِ ﴿يُعَذِّبكُمْ عَذابًا ألِيمًا﴾ مُؤْلِمًا ﴿ويَسْتَبْدِل قَوْمًا غَيْركُمْ﴾ أيْ يَأْتِ بِهِمْ بَدَلكُمْ ﴿ولا تَضُرُّوهُ﴾ أيْ اللَّه أوْ النَّبِيّ ﷺ ﴿شَيْئًا﴾ بِتَرْكِ نَصْره فَإنَّ اللَّه ناصِر دِينه ﴿واللَّه عَلى كُلّ شَيْء قَدِير﴾ ومِنهُ نَصْر دِينه ونَبِيّه"],[40,40,"﴿إلّا تَنْصُرُوهُ﴾ أيْ النَّبِيّ ﷺ ﴿فَقَدْ نَصَرَهُ اللَّه إذْ﴾ حِين ﴿أخْرَجَهُ الَّذِينَ كَفَرُوا﴾ مِن مَكَّة أيْ ألْجَئُوهُ إلى الخُرُوج لَمّا أرادُوا قَتْله أوْ حَبْسه أوْ نَفْيه بِدارِ النَّدْوَة ﴿ثانِي اثْنَيْنِ﴾ حال أيْ أحَد اثْنَيْنِ والآخَر أبُو بَكْر - المَعْنى نَصَرَهُ اللَّه فِي مِثْل تِلْكَ الحالَة فَلا يَخْذُلهُ فِي غَيْرها - ﴿إذْ﴾ بَدَل مِن إذْ قَبْله ﴿هُما فِي الغار﴾ نَقْب فِي جَبَل ثَوْر ﴿إذْ﴾ بَدَل ثانٍ ﴿يَقُول لِصاحِبِهِ﴾ أبِي بَكْر وقَدْ قالَ لَهُ لَمّا رَأى أقْدام المُشْرِكِينَ: لَوْ نَظَرَ أحَدهمْ تَحْت قَدَمَيْهِ لَأَبْصَرَنا ﴿لا تَحْزَن إنّ اللَّه مَعَنا﴾ بِنَصْرِهِ ﴿فَأَنْزَلَ اللَّه سَكِينَته﴾ طُمَأْنِينَته ﴿عَلَيْهِ﴾ قِيلَ عَلى النَّبِيّ ﷺ وقِيلَ عَلى أبِي بَكْر ﴿وأَيَّدَهُ﴾ أيْ النَّبِيّ ﷺ ﴿بِجُنُودٍ لَمْ تَرَوْها﴾ مَلائِكَة فِي الغار ومَواطِن قِتاله ﴿وجَعَلَ كَلِمَة الَّذِينَ كَفَرُوا﴾ أيْ دَعْوَة الشِّرْك ﴿السُّفْلى﴾ المَغْلُوبَة ﴿وكَلِمَة اللَّه﴾ أيْ كَلِمَة الشَّهادَة ﴿هِيَ العُلْيا﴾ الظّاهِرَة الغالِبَة ﴿واللَّه عَزِيز﴾ فِي مُلْكه ﴿حَكِيم﴾ فِي صُنْعه"],[41,41,"﴿انْفِرُوا خِفافًا وثِقالًا﴾ نَشاطًا وغَيْر نَشاط وقِيلَ أقْوِياء وضُعَفاء أوْ أغْنِياء وفُقَراء وهِيَ مَنسُوخَة بِآيَةِ ﴿لَيْسَ عَلى الضُّعَفاء﴾ ﴿وجاهِدُوا بِأَمْوالِكُمْ وأَنْفُسكُمْ فِي سَبِيل اللَّه ذَلِكُمْ خَيْر لَكُمْ إنْ كُنْتُمْ تَعْلَمُونَ﴾ أنَّهُ خَيْر لَكُمْ فَلا تَثّاقَلُوا"],[42,42,"﴿لَوْ كانَ﴾ ما دَعَوْتهمْ إلَيْهِ، ونَزَلَ فِي المُنافِقِينَ الَّذِينَ تَخَلَّفُوا ﴿عَرَضًا﴾ مَتاعًا مِن الدُّنْيا ﴿قَرِيبًا﴾ سَهْل المَأْخَذ ﴿وسَفَرًا قاصِدًا﴾ وسَطًا ﴿لاتَّبَعُوك﴾ طَلَبًا لِلْغَنِيمَةِ ﴿ولَكِنْ بَعُدَتْ عَلَيْهِمْ الشُّقَّة﴾ المَسافَة فَتَخَلَّفُوا ﴿وسَيَحْلِفُونَ بِاللَّهِ﴾ إذا رَجَعْتُمْ إلَيْهِمْ ﴿لَوْ اسْتَطَعْنا﴾ الخُرُوج ﴿لَخَرَجْنا مَعَكُمْ يُهْلِكُونَ أنْفُسهمْ﴾ بِالحَلِفِ الكاذِب ﴿واللَّه يَعْلَم إنّهُمْ لَكاذِبُونَ﴾ فِي قَوْلهمْ ذَلِكَ"],[43,43,"وكانَ ﷺ أذَّنَ لِجَماعَةٍ فِي التَّخَلُّف بِاجْتِهادٍ مِنهُ فَنَزَلَ عِتابًا لَهُ وقَدَّمَ العَفْو تَطْمِينًا لِقَلْبِهِ ﴿عَفا اللَّه عَنْك لِمَ أذِنْت لَهُمْ﴾ فِي التَّخَلُّف وهَلّا تَرَكْتهمْ، ﴿حَتّى يَتَبَيَّن لَك الَّذِينَ صَدَقُوا﴾ فِي العُذْر ﴿وتَعْلَم الكاذِبِينَ﴾ فِيهِ"],[44,44,"﴿لا يَسْتَأْذِنك الَّذِينَ يُؤْمِنُونَ بِاللَّهِ واليَوْم الآخِر﴾ فِي التَّخَلُّف عَنْ ﴿أنْ يُجاهِدُوا بِأَمْوالِهِمْ وأَنْفُسهمْ﴾"],[45,45,"﴿إنّما يَسْتَأْذِنك﴾ فِي التَّخَلُّف ﴿الَّذِينَ لا يُؤْمِنُونَ بِاللَّهِ واليَوْم الآخِر وارْتابَتْ﴾ شَكَّتْ ﴿قُلُوبهمْ﴾ فِي الدِّين ﴿فَهُمْ فِي رَيْبهمْ يَتَرَدَّدُونَ﴾ يَتَحَيَّرُونَ"],[46,46,"﴿ولَوْ أرادُوا الخُرُوج﴾ مَعَك ﴿لَأَعَدُّوا لَهُ عُدَّة﴾ أُهْبَة مِن الآلَة والزّاد ﴿ولَكِنْ كَرِهَ اللَّه انْبِعاثهمْ﴾ أيْ لَمْ يُرِدْ خُرُوجهمْ ﴿فَثَبَّطَهُمْ﴾ كَسَّلَهُمْ ﴿وقِيلَ﴾ وقِيلَ لَهُمْ ﴿اُقْعُدُوا مَعَ القاعِدِينَ﴾ المَرْضى والنِّساء والصِّبْيان أيْ قَدَّرَ اللَّه تَعالى ذَلِكَ"],[47,47,"﴿لَوْ خَرَجُوا فِيكُمْ ما زادُوكُمْ إلّا خَبالًا﴾ فَسادُوا بِتَخْذِيلِ المُؤْمِنِينَ ﴿ولَأَوْضَعُوا خِلالكُمْ﴾ أيْ أسْرَعُوا بَيْنكُمْ بِالمَشْيِ بِالنَّمِيمَةِ ﴿يَبْغُونَكُمْ﴾ يَطْلُبُونَ لَكُمْ ﴿الفِتْنَة﴾ بِإلْقاءِ العَداوَة ﴿وفِيكُمْ سَمّاعُونَ لَهُمْ﴾ ما يَقُولُونَ سَماع قَبُول"],[48,48,"﴿لَقَدْ ابْتَغَوْا﴾ لَك ﴿الفِتْنَة مِن قَبْل﴾ أوَّل ما قَدِمْت المَدِينَة ﴿وقَلَبُوا لَك الأُمُور﴾ أيْ أجالُوا الفِكْر فِي كَيْدك وإبْطال دِينك ﴿حَتّى جاءَ الحَقّ﴾ النَّصْر ﴿وظَهَرَ﴾ عَزَّ ﴿أمْر اللَّه﴾ دِينه ﴿وهُمْ كارِهُونَ﴾ لَهُ فَدَخَلُوا فِيهِ ظاهِرًا"],[49,49,"﴿ومِنهُمْ مَن يَقُول ائْذَنْ لِي﴾ فِي التَّخَلُّف ﴿ولا تَفْتِنِّي﴾ وهُوَ الجَدّ بْن قَيْس قالَ لَهُ النَّبِيّ ﷺ: \"هَلْ لَك فِي جَلّاد بَنِي الأَصْفَر ؟\" فَقالَ: إنِّي مُغْرَم بِالنِّساءِ وأَخْشى إنْ رَأَيْت نِساء بَنِي الأَصْفَر أنْ لا أصْبِر عَنْهُنَّ فَأُفْتَتَن ﴿ألا فِي الفِتْنَة سَقَطُوا﴾ بِالتَّخَلُّفِ وقُرِئَ سَقَطَ ﴿وإنَّ جَهَنَّم لَمُحِيطَة بِالكافِرِينَ﴾ لا مَحِيص لَهُمْ عَنْها"],[50,50,"﴿إنْ تُصِبْك حَسَنَة﴾ كَنَصْرٍ وغَنِيمَة ﴿تَسُوءهُمْ وإنْ تُصِبْك مُصِيبَة﴾ شِدَّة ﴿يَقُولُوا قَدْ أخَذْنا أمْرنا﴾ بِالحَزْمِ حِين تَخَلَّفْنا ﴿مِن قَبْل﴾ قَبْل هَذِهِ المَعْصِيَة ﴿ويَتَوَلَّوْا وهُمْ فَرِحُونَ﴾ بِما أصابَك"],[51,51,"﴿قُلْ﴾ لَهُمْ ﴿لَنْ يُصِيبنا إلّا ما كَتَبَ اللَّه لَنا﴾ إصابَته ﴿هُوَ مَوْلانا﴾ ناصِرنا ومُتَوَلِّي أُمُورنا"],[52,52,"﴿قُلْ هَلْ تَرَبَّصُونَ﴾ فِيهِ حَذْف إحْدى التّاءَيْنِ مِن الأَصْل أيْ تَنْتَظِرُونَ أنْ يَقَع ﴿بِنا إلّا إحْدى﴾ العاقِبَتَيْنِ ﴿الحُسْنَيَيْنِ﴾ تَثْنِيَة حُسْنى تَأْنِيث أحْسَن: النَّصْر أوْ الشَّهادَة ﴿ونَحْنُ نَتَرَبَّص﴾ نَنْتَظِر ﴿بِكُمْ أنْ يُصِيبكُمْ اللَّه بِعَذابٍ مِن عِنْده﴾ بِقارِعَةٍ مِن السَّماء ﴿أوْ بِأَيْدِينا﴾ بِأَنْ يُؤْذِن لَنا فِي قِتالكُمْ ﴿فَتَرَبَّصُوا﴾ بِنا ذَلِكَ ﴿إنّا مَعَكُمْ مُتَرَبِّصُونَ﴾ عاقِبَتكُمْ"],[53,53,"﴿قُلْ أنْفِقُوا﴾ فِي طاعَة اللَّه ﴿طَوْعًا أوْ كَرْهًا لَنْ يُتَقَبَّل مِنكُمْ﴾ ما أنْفَقْتُمُوهُ والأَمْر هُنا بِمَعْنى الخَبَر"],[54,54,"﴿وما مَنَعَهُمْ أنْ تُقْبَل﴾ بِالتّاءِ والياء ﴿مِنهُمْ نَفَقاتهمْ إلّا﴾ فاعِل وأَنْ تُقْبَل مَفْعُول ﴿كَفَرُوا بِاللَّهِ وبِرَسُولِهِ ولا يَأْتُونَ الصَّلاة إلّا وهُمْ كُسالى﴾ مُتَثاقِلُونَ ﴿ولا يُنْفِقُونَ إلّا وهُمْ كارِهُونَ﴾ النَّفَقَة لِأَنَّهُمْ يَعُدُّونَها مَغْرَمًا"],[55,55,"﴿فَلا تُعْجِبك أمْوالهمْ ولا أوْلادهمْ﴾ أيْ لا تَسْتَحْسِن نِعَمنا عَلَيْهِمْ فَهِيَ اسْتِدْراج ﴿إنّما يُرِيد اللَّه لِيُعَذِّبهُمْ﴾ أيْ أنْ يُعَذِّبهُمْ ﴿بِها فِي الحَياة الدُّنْيا﴾ بِما يَلْقَوْنَ فِي جَمْعها مِن المَشَقَّة وفِيها مِن المَصائِب ﴿وتَزْهَق﴾ تَخْرُج ﴿أنْفُسهمْ وهُمْ كافِرُونَ﴾ فَيُعَذِّبهُمْ فِي الآخِرَة أشَدّ العَذاب"],[56,56,"﴿ويَحْلِفُونَ بِاللَّهِ إنّهُمْ لِمِنكُمْ﴾ أيْ مُؤْمِنُونَ ﴿وما هُمْ مِنكُمْ ولَكِنَّهُمْ قَوْم يَفْرُقُونَ﴾ يَخافُونَ أنْ تَفْعَلُوا بِهِمْ كالمُشْرِكِينَ فَيَحْلِفُونَ تَقِيَّة"],[57,57,"﴿لَوْ يَجِدُونَ مَلْجَأ﴾ يَلْجَئُونَ إلَيْهِ ﴿أوْ مَغارات﴾ سَرادِيب ﴿أوْ مُدَّخَلًا﴾ مَوْضِعًا يَدْخُلُونَهُ ﴿لَوَلَّوْا إلَيْهِ وهُمْ يَجْمَحُونَ﴾ يُسْرِعُونَ فِي دُخُوله والِانْصِراف عَنْكُمْ إسْراعًا لا يَرُدّهُ شَيْء كالفَرَسِ الجَمُوح"],[58,58,"﴿ومِنهُمْ مَن يَلْمِزك﴾ يَعِيبك ﴿فِي﴾ قَسْم"],[59,59,"﴿ولَوْ أنَّهُمْ رَضُوا ما آتاهُمْ اللَّه ورَسُوله﴾ مِن الغَنائِم ونَحْوها ﴿وقالُوا حَسْبنا﴾ كافِينا ﴿اللَّه سَيُؤْتِينا اللَّه مِن فَضْله ورَسُوله﴾ مِن غَنِيمَة أُخْرى ما يَكْفِينا ﴿إنّا إلى اللَّه راغِبُونَ﴾ أنْ يُغْنِينا وجَواب لَوْ لَكانَ خَيْرًا لَهُمْ"],[60,60,"﴿إنّما الصَّدَقات﴾ الزَّكَوات مَصْرُوفَة ﴿لِلْفُقَراءِ﴾ الَّذِينَ لا يَجِدُونَ ما يَقَع مَوْقِعًا مِن كِفايَتهمْ ﴿والمَساكِين﴾ الَّذِينَ لا يَجِدُونَ ما يَكْفِيهِمْ ﴿والعامِلِينَ عَلَيْها﴾ أيْ الصَّدَقات مِن جابٍ وقاسِم وكاتِب وحاشِر ﴿والمُؤَلَّفَة قُلُوبهمْ﴾ لِيُسْلِمُوا أوْ يَثْبُت إسْلامهمْ أوْ يَسْلَم نُظَراؤُهُمْ أوْ يَذُبُّوا عَنْ المُسْلِمِينَ أقْسام الأَوَّل والأَخِير لا يُعْطِيانِ اليَوْم عِنْد الشّافِعِيّ رَضِيَ اللَّه تَعالى عَنْهُ لِعَزِّ الإسْلام بِخِلافِ الآخَرَيْنِ فَيُعْطِيانِ عَلى الأَصَحّ ﴿وفِي﴾ فَكّ ﴿الرِّقاب﴾ أيْ المُكاتَبِينَ ﴿والغارِمِينَ﴾ أهْل الدِّين إنْ اسْتَدانُوا لِغَيْرِ مَعْصِيَة أوْ تابُوا ولَيْسَ لَهُمْ وفاء أوْ لِإصْلاحِ ذات البَيْن ولَوْ أغْنِياء ﴿وفِي سَبِيل اللَّه﴾ أيْ القائِمِينَ بِالجِهادِ مِمَّنْ لا فَيْء لَهُمْ ولَوْ أغْنِياء ﴿وابْن السَّبِيل﴾ المُنْقَطِع فِي سَفَره ﴿فَرِيضَة﴾ نُصِبَ بِفِعْلِهِ المُقَدَّر ﴿مِن اللَّه واللَّه عَلِيم﴾ بِخَلْقِهِ ﴿حَكِيم﴾ فِي صُنْعه فَلا يَجُوز صَرْفها لِغَيْرِ هَؤُلاءِ ولا مَنع صِنْف مِنهُمْ إذا وُجِدَ فَيَقْسِمها الإمام عَلَيْهِمْ عَلى السَّواء ولَهُ تَفْضِيل بَعْض آحاد الصِّنْف عَلى بَعْض وأَفادَتْ اللّام وُجُوب اسْتِغْراق أفْراده لَكِنْ لا يَجِب عَلى صاحِب المال إذا قَسَمَ لِعُسْرِهِ بَلْ يَكْفِي إعْطاء ثَلاثَة مِن كُلّ صِنْف ولا يَكْفِي دُونها كَما أفادَتْهُ صِيغَة الجَمْع وبَيَّنَتْ السُّنَّة أنَّ شَرْط المُعْطى مِنها الإسْلام وأَنْ لا يَكُون هاشِمِيًّا ولا مُطَّلِبِيًّا"],[61,61,"﴿ومِنهُمْ﴾ أيْ المُنافِقِينَ ﴿الَّذِينَ يُؤْذُونَ النَّبِيّ﴾ بِعَيْبِهِ وبِنَقْلِ حَدِيثه ﴿ويَقُولُونَ﴾ إذا نُهُوا عَنْ ذَلِكَ لِئَلّا يُبَلِّغهُ ﴿هُوَ أُذُن﴾ أيْ يَسْمَع كُلّ قَيْل ويَقْبَلهُ فَإذا حَلَفْنا لَهُ أنّا لَمْ نَقُلْ صَدَّقْنا ﴿قُلْ﴾ هُوَ ﴿أُذُن﴾ مُسْتَمِع ﴿خَيْر لَكُمْ﴾ لا مُسْتَمِع شَرّ ﴿يُؤْمِن بِاللَّهِ ويُؤْمِن﴾ يُصَدِّق ﴿لِلْمُؤْمِنِينَ﴾ فِيما أخْبَرُوهُ بِهِ لا لِغَيْرِهِمْ واللّام زائِدَة لِلْفَرَقِ بَيْن إيمان التَّسْلِيم وغَيْره ﴿ورَحْمَة﴾ بِالرَّفْعِ عَطْفًا عَلى أُذُن والجَرّ عَطْفًا عَلى خَيْر"],[62,62,"﴿يَحْلِفُونَ بِاللَّهِ لَكُمْ﴾ أيّها المُؤْمِنُونَ فِيما بَلَغَكُمْ عَنْهُمْ مِن أذى الرَّسُول أنَّهُمْ ما أتَوْهُ ﴿لِيُرْضُوكُمْ واللَّه ورَسُوله أحَقّ أنْ يُرْضُوهُ﴾ بِالطّاعَةِ وتَوْحِيد الضَّمِير لِتَلازُمِ الرِّضاءَيْنِ أوْ خَبَر اللَّه ورَسُوله مَحْذُوف ﴿إنْ كانُوا مُؤْمِنِينَ﴾ حَقًّا"],[63,63,"﴿ألَمْ يَعْلَمُوا﴾ بِ ﴿أنَّهُ﴾ أيْ الشَّأْن ﴿مَن يُحادِدْ﴾ يُشاقِقْ ﴿اللَّه ورَسُوله فَإنَّ لَهُ نار جَهَنَّم﴾ جَزاء"],[64,64,"﴿يَحْذَر﴾ يَخاف ﴿المُنافِقُونَ أنْ تُنَزَّلَ عَلَيْهِمْ﴾ أيْ المُؤْمِنِينَ ﴿سُورَة تُنَبِّئهُمْ بِما فِي قُلُوبهمْ﴾ مِن النِّفاق وهُمْ مَعَ ذَلِكَ يَسْتَهْزِئُونَ ﴿قُلْ اسْتَهْزِئُوا﴾ أمْر تَهْدِيد ﴿إنّ اللَّه مُخْرِج﴾ مُظْهِر ﴿ما تَحْذَرُونَ﴾ إخْراجه مِن نِفاقكُمْ"],[65,65,"﴿ولَئِنْ﴾ لام قَسَم ﴿سَأَلْتهمْ﴾ عَنْ اسْتِهْزائِهِمْ بِك والقُرْآن وهُمْ سائِرُونَ مَعَك إلى تَبُوك\" ﴿﴾ \"لَيَقُولُنَّ\" ﴿مُعْتَذِرِينَ﴾ \"إنّما كُنّا نَخُوض ونَلْعَب\" ﴿فِي الحَدِيث لِنَقْطَع بِهِ الطَّرِيق ولَمْ نَقْصِد ذَلِكَ﴾ \"قُلْ\" ﴿لَهُمْ﴾"],[66,66,"﴿لا تَعْتَذِرُوا﴾ عَنْهُ ﴿قَدْ كَفَرْتُمْ بَعْد إيمانكُمْ﴾ أيْ ظَهَرَ كُفْركُمْ بَعْد إظْهار الإيمان ﴿إنْ يُعْفَ﴾ بِالياءِ مَبْنِيًّا لِلْمَفْعُولِ والنُّون مَبْنِيًّا لِلْفاعِلِ ﴿عَنْ طائِفَة مِنكُمْ﴾ بِإخْلاصِها وتَوْبَتها كَجَحْشِ بْن حِمْيَر ﴿نُعَذِّب﴾ بِالتّاءِ والنُّون ﴿طائِفَة بِأَنَّهُمْ كانُوا مُجْرِمِينَ﴾ مُصِرِّينَ عَلى النِّفاق والِاسْتِهْزاء"],[67,67,"﴿المُنافِقُونَ والمُنافِقات بَعْضهمْ مِن بَعْض﴾ أيْ مُتَشابِهُونَ فِي الدِّين كَأَبْعاضِ الشَّيْء الواحِد ﴿يَأْمُرُونَ بِالمُنْكَرِ﴾ الكُفْر والمَعاصِي ﴿ويَنْهَوْنَ عَنْ المَعْرُوف﴾ الإيمان والطّاعَة ﴿ويَقْبِضُونَ أيْدِيهمْ﴾ عَنْ الإنْفاق فِي الطّاعَة ﴿نَسُوا اللَّه﴾ تَرَكُوا طاعَته ﴿فَنَسِيَهُمْ﴾ تَرَكَهُمْ مِن لُطْفه"],[68,68,"﴿وعَدَ اللَّه المُنافِقِينَ والمُنافِقات والكُفّار نار جَهَنَّم خالِدِينَ فِيها هِيَ حَسْبهمْ﴾ جَزاء وعِقابًا ﴿ولَعَنَهُمْ اللَّه﴾ أبْعَدهمْ عَنْ رَحْمَته\" ﴿﴾ \"ولَهُمْ عَذاب مُقِيم\" ﴿دائِم﴾"],[69,69,"أنْتُمْ أيّها المُنافِقُونَ ﴿كالَّذِينَ مِن قَبْلكُمْ كانُوا أشَدّ مِنكُمْ قُوَّة وأَكْثَر أمْوالًا وأَوْلادًا فاسْتَمْتَعُوا﴾ تَمَتَّعُوا ﴿بِخَلاقِهِمْ﴾ نَصِيبهمْ مِن الدُّنْيا ﴿فاسْتَمْتَعْتُمْ﴾ أيّها المُنافِقُونَ ﴿بِخَلاقِكُمْ كَما اسْتَمْتَعَ الَّذِينَ مِن قَبْلكُمْ بِخَلاقِهِمْ وخُضْتُمْ﴾ فِي الباطِل والطَّعْن فِي النَّبِيّ ﷺ ﴿كالَّذِي خاضُوا﴾ أيْ كَخَوْضِهِمْ"],[70,70,"﴿ألَمْ يَأْتِهِمْ نَبَأ﴾ خَبَر ﴿الَّذِينَ مِن قَبْلهمْ قَوْم نُوح وعاد﴾ قَوْم هُود ﴿وثَمُود﴾ قَوْم صالِح ﴿وقَوْم إبْراهِيم وأَصْحاب مَدْيَن﴾ قَوْم شُعَيْب ﴿والمُؤْتَفِكات﴾ قُرى قَوْم لُوط أيْ أهْلها ﴿أتَتْهُمْ رُسُلهمْ بِالبَيِّناتِ﴾ بِالمُعْجِزاتِ فَكَذَبُوهُمْ فَأُهْلِكُوا ﴿فَما كانَ اللَّه لِيَظْلِمهُمْ﴾ بِأَنْ يُعَذِّبهُمْ بِغَيْرِ ذَنْب ﴿ولَكِنْ كانُوا أنْفُسهمْ يَظْلِمُونَ﴾ بِارْتِكابِ الذَّنْب"],[71,71,"﴿والمُؤْمِنُونَ والمُؤْمِنات بَعْضهمْ أوْلِياء بَعْض يَأْمُرُونَ بِالمَعْرُوفِ ويَنْهَوْنَ عَنْ المُنْكَر ويُقِيمُونَ الصَّلاة ويُؤْتُونَ الزَّكاة ويُطِيعُونَ اللَّه ورَسُوله أُولَئِكَ سَيَرْحَمُهُمْ اللَّه إنّ اللَّه عَزِيز﴾ لا يُعْجِزهُ شَيْء عَنْ إنْجاز وعْده ووَعِيده ﴿حَكِيم﴾ لا يَضَع شَيْئًا إلّا فِي مَحَلّه"],[72,72,"﴿وعَدَ اللَّه المُؤْمِنِينَ والمُؤْمِنات جَنّات تَجْرِي مِن تَحْتها الأَنْهار خالِدِينَ فِيها ومَساكِن طَيِّبَة فِي جَنّات عَدْن﴾ إقامَة ﴿ورِضْوان مِن اللَّه أكْبَر﴾ أعْظَم مِن ذَلِكَ كُلّه"],[73,73,"﴿يا أيّها النَّبِيّ جاهِد الكُفّار﴾ بِالسَّيْفِ ﴿والمُنافِقِينَ﴾ بِاللِّسانِ والحُجَّة ﴿واغْلُظْ عَلَيْهِمْ﴾ بِالِانْتِهارِ والمَقْت ﴿ومَأْواهُمْ جَهَنَّم وبِئْسَ المَصِير﴾ المَرْجِع هِيَ"],[74,74,"﴿يَحْلِفُونَ﴾ أيْ المُنافِقُونَ ﴿بِاللَّهِ ما قالُوا﴾ ما بَلَغَك عَنْهُمْ مِن السَّبّ ﴿ولَقَدْ قالُوا كَلِمَة الكُفْر وكَفَرُوا بَعْد إسْلامهمْ﴾ أظْهَرُوا الكُفْر بَعْد إظْهار الإسْلام\" ﴿﴾ \"وهَمُّوا بِما لَمْ يَنالُوا\" ﴿مِن الفَتْك بِالنَّبِيِّ لَيْلَة العَقَبَة عِنْد عَوْده مِن تَبُوك وهُمْ بَضْعَة عَشَرَ رَجُلًا فَضَرَبَ عَمّار بْن ياسِر وُجُوه الرَّواحِل لَمّا غَشُوهُ فَرُدُّوا﴾ \"وما نَقَمُوا\" ﴿أنْكَرُوا﴾ \"إلّا أنْ أغْناهُمْ اللَّه ورَسُوله مِن فَضْله\" ﴿بِالغَنائِمِ بَعْد شِدَّة حاجَتهمْ، المَعْنى لَمْ يَنَلْهُمْ مِنهُ إلّا هَذا ولَيْسَ مِمّا يَنْقِم﴾ \"فَإنْ يَتُوبُوا\" ﴿عَنْ النِّفاق ويُؤْمِنُوا بِك﴾ \"يَكُ خَيْرًا لَهُمْ وإنْ يَتَوَلَّوْا\" ﴿عَنْ الإيمان﴾ \"يُعَذِّبهُمْ اللَّه عَذابًا ألِيمًا فِي الدُّنْيا\" ﴿بِالقَتْلِ﴾ \"والآخِرَة\" ﴿بِالنّارِ﴾ \"وما لَهُمْ فِي الأَرْض مِن ولِيّ\" ﴿يَحْفَظهُمْ مِنهُ﴾ \"ولا نَصِير\" ﴿يَمْنَعهُمْ﴾"],[75,75,"﴿ومِنهُمْ مَن عاهَدَ اللَّه لَئِنْ آتانا مِن فَضْله لَنَصَّدَّقَنَّ﴾ فِيهِ إدْغام التّاء فِي الأَصْل فِي الصّاد ﴿ولَنَكُونَنَّ مِن الصّالِحِينَ﴾ وهُوَ ثَعْلَبَة بْن حاطِب سَأَلَ النَّبِيّ ﷺ أنْ يَدْعُو لَهُ أنْ يَرْزُقهُ اللَّه مالًا ويُؤَدِّي مِنهُ كُلّ ذِي حَقّ حَقّه فَدَعا لَهُ فَوَسَّعَ عَلَيْهِ فانْقَطَعَ عَنْ الجُمُعَة والجَماعَة ومَنَعَ الزَّكاة"],[76,76,"﴿فَلَمّا آتاهُمْ مِن فَضْله بَخِلُوا بِهِ وتَوَلَّوْا﴾ عَنْ طاعَة اللَّه"],[77,77,"﴿فَأَعْقَبَهُمْ﴾ أيْ فَصَيَّرَ عاقِبَتهمْ ﴿نِفاقًا﴾ ثابِتًا ﴿فِي قُلُوبهمْ إلى يَوْم يَلْقَوْنَهُ﴾ أيْ اللَّه وهُوَ يَوْم القِيامَة فَجاءَ بَعْد ذَلِكَ إلى النَّبِيّ ﷺ بِزَكاتِهِ فَقالَ: إنّ اللَّه مَنَعَنِي أنْ أقْبَلَ مِنك فَجَعَلَ يَحْثُو التُّراب عَلى رَأْسه ثُمَّ جاءَ إلى أبِي بَكْر فَلَمْ يَقْبَلها ثُمَّ إلى عُمَر فَلَمْ يَقْبَلها ثُمَّ إلى عُثْمان فَلَمْ يَقْبَلها وماتَ فِي زَمانه"],[78,78,"﴿ألَمْ يَعْلَمُوا﴾ أيْ المُنافِقُونَ ﴿أنَّ اللَّه يَعْلَم سِرّهمْ﴾ ما أسَرُّوهُ فِي أنْفُسهمْ ﴿ونَجْواهُمْ﴾ ما تَناجَوْا بِهِ بَيْنهمْ ﴿وأَنَّ اللَّه عَلّام الغُيُوب﴾ ما غابَ عَنْ العِيان، ولَمّا نَزَلَتْ آيَة الصَّدَقَة جاءَ رَجُل فَتَصَدَّقَ بِشَيْءٍ كَثِير فَقالَ المُنافِقُونَ: مُراءٍ وجاءَ رَجُل فَتَصَدَّقَ بِصاعٍ فَقالُوا: إنّ اللَّه غَنِيّ عَنْ صَدَقَة هَذا فَنَزَلَ"],[79,79,"﴿الَّذِينَ﴾ مُبْتَدَأ ﴿يَلْمِزُونَ﴾ يَعِيبُونَ ﴿المُطَّوِّعِينَ﴾ المُتَنَفِّلِينَ ﴿مِن المُؤْمِنِينَ فِي الصَّدَقات والَّذِينَ لا يَجِدُونَ إلّا جُهْدهمْ﴾ طاقَتهمْ فَيَأْتُونَ بِهِ ﴿فَيَسْخَرُونَ مِنهُمْ﴾ والخَبَر ﴿سَخِرَ اللَّه مِنهُمْ﴾ جازاهُمْ عَلى سُخْرِيَتهمْ"],[80,80,"﴿اسْتَغْفِرْ﴾ يا مُحَمَّد ﴿لَهُمْ أوْ لا تَسْتَغْفِر لَهُمْ﴾ تَخْيِير لَهُ فِي الِاسْتِغْفار وتَرْكه قالَ ﷺ: \"إنِّي خُيِّرْت فاخْتَرْت يَعْنِي الِاسْتِغْفار\" رَواهُ البُخارِيّ ﴿إنْ تَسْتَغْفِر لَهُمْ سَبْعِينَ مَرَّة فَلَنْ يَغْفِر اللَّه لَهُمْ﴾ قِيلَ المُراد بِالسَّبْعِينَ المُبالَغَة فِي كَثْرَة الِاسْتِغْفار وفِي البُخارِيّ حَدِيث \"لَوْ أعْلَم أنِّي لَوْ زِدْت عَلى السَّبْعِينَ غُفِرَ لَزِدْت عَلَيْها\" وقِيلَ المُراد العَدَد المَخْصُوص لِحَدِيثِهِ أيْضًا وسَأَزِيدُ عَلى السَّبْعِينَفَبَيَّنَ لَهُ حَسْم المَغْفِرَة بِآيَةِ ﴿سَواء عَلَيْهِمْ أسْتَغْفَرْت لَهُمْ أمْ لَمْ تَسْتَغْفِر لَهُمْ﴾"],[81,81,"﴿فَرِحَ المُخَلَّفُونَ﴾ عَنْ تَبُوك ﴿بِمَقْعَدِهِمْ﴾ أيْ بِقُعُودِهِمْ ﴿خِلاف﴾ أيْ بَعْد ﴿رَسُول اللَّه وكَرِهُوا أنْ يُجاهِدُوا بِأَمْوالِهِمْ وأَنْفُسهمْ فِي سَبِيل اللَّه وقالُوا﴾ أيْ قالَ بَعْضهمْ لِبَعْضٍ ﴿لا تَنْفِرُوا﴾ تَخْرُجُوا إلى الجِهاد ﴿فِي الحَرّ قُلْ نار جَهَنَّم أشَدّ حَرًّا﴾ مِن تَبُوك فالأَوْلى أنْ يَتَّقُوها بِتَرْكِ التَّخَلُّف ﴿لَوْ كانُوا يَفْقَهُونَ﴾ يَعْلَمُونَ ذَلِكَ ما تَخَلَّفُوا"],[82,82,"﴿فَلْيَضْحَكُوا قَلِيلًا﴾ فِي الدُّنْيا ﴿ولْيَبْكُوا﴾ فِي الآخِرَة وهُوَ خَبَر عَنْ حالهمْ بِصِيغَةِ الأَمْر"],[83,83,"﴿فَإنْ رَجَعَك﴾ رَدَّك ﴿اللَّه﴾ مِن تَبُوك ﴿إلى طائِفَة مِنهُمْ﴾ مِمَّنْ تَخَلَّفَ بِالمَدِينَةِ مِن المُنافِقِينَ ﴿فاسْتَأْذَنُوك لِلْخُرُوجِ﴾ مَعَك إلى غَزْوَة أُخْرى ﴿فَقُلْ﴾ لَهُمْ ﴿لَنْ تَخْرُجُوا مَعِي أبَدًا ولَنْ تُقاتِلُوا مَعِي عَدُوًّا إنّكُمْ رَضِيتُمْ بِالقُعُودِ أوَّل مَرَّة فاقْعُدُوا مَعَ الخالِفِينَ﴾ المُتَخَلِّفِينَ عَنْ الغَزْو مِن النِّساء والصِّبْيان وغَيْرهمْ"],[84,84,"ولَمّا صَلّى النَّبِيّ ﷺ عَلى ابْن أُبَيٍّ نَزَلَ ﴿ولا تُصَلِّ عَلى أحَد مِنهُمْ ماتَ أبَدًا ولا تَقُمْ عَلى قَبْره﴾ لِدَفْنٍ أوْ زِيارَة ﴿إنّهُمْ كَفَرُوا بِاللَّهِ ورَسُوله وماتُوا وهُمْ فاسِقُونَ﴾ كافِرُونَ"],[85,85,"﴿ولا تُعْجِبك أمْوالهمْ وأَوْلادهمْ إنّما يُرِيد اللَّه أنْ يُعَذِّبهُمْ بِها فِي الدُّنْيا وتَزْهَق﴾ تَخْرُج"],[86,86,"﴿وإذا أُنْزِلَتْ سُورَة﴾ أيْ طائِفَة مِن القُرْآن ﴿أنْ﴾ أيْ بِأَنْ ﴿آمِنُوا بِاللَّهِ وجاهِدُوا مَعَ رَسُوله اسْتَأْذَنَك أُولُو الطَّوْل﴾ ذَوُو الغِنى"],[87,87,"﴿رَضُوا بِأَنْ يَكُونُوا مَعَ الخَوالِف﴾ جَمْع خالِفَة أيْ النِّساء اللّاتِي تَخَلَّفْنَ فِي البُيُوت ﴿وطُبِعَ عَلى قُلُوبهمْ فَهُمْ لا يَفْقَهُونَ﴾ الخَيْر"],[88,88,"﴿لَكِنْ الرَّسُول والَّذِينَ آمَنُوا مَعَهُ جاهَدُوا بِأَمْوالِهِمْ وأَنْفُسهمْ وأُولَئِكَ لَهُمْ الخَيْرات﴾ فِي الدُّنْيا والآخِرَة ﴿وأُولَئِكَ هُمْ المُفْلِحُونَ﴾ أيْ الفائِزُونَ"],[90,90,"﴿وجاءَ المُعَذِّرُونَ﴾ بِإدْغامِ التّاء فِي الأَصْل فِي الدّال أيْ المُعْتَذِرُونَ بِمَعْنى المَعْذُورِينَ وقُرِئَ بِهِ ﴿مِن الأَعْراب﴾ إلى النَّبِيّ ﷺ ﴿لِيُؤْذَن لَهُمْ﴾ فِي القُعُود لِعُذْرِهِمْ فَأَذِنَ لَهُمْ ﴿وقَعَدَ الَّذِينَ كَذَبُوا اللَّه ورَسُوله﴾ فِي ادِّعاء الإيمان مِن مُنافِقِي الأَعْراب عَنْ المَجِيء لِلِاعْتِذارِ"],[91,91,"﴿لَيْسَ عَلى الضُّعَفاء﴾ كالشُّيُوخِ ﴿ولا عَلى المَرْضى﴾ كالعُمْيِ. والزَّمْنى ﴿ولا عَلى الَّذِينَ لا يَجِدُونَ ما يُنْفِقُونَ﴾ فِي الجِهاد ﴿حَرَج﴾ إثْم فِي التَّخَلُّف عَنْهُ ﴿إذا نَصَحُوا لِلَّهِ ورَسُوله﴾ فِي حال قُعُودهمْ بِعَدَمِ الإرْجاف والتَّثْبِيط والطّاعَة ﴿ما عَلى المُحْسِنِينَ﴾ بِذَلِكَ ﴿مِن سَبِيل﴾ طَرِيق بِالمُؤاخَذَةِ ﴿واللَّه غَفُور﴾ لَهُمْ ﴿رَحِيم﴾ بِهِمْ فِي التَّوْسِعَة فِي ذَلِكَ"],[92,92,"﴿ولا عَلى الَّذِينَ إذا ما أتَوْك لِتَحْمِلهُمْ﴾ مَعَك إلى الغَزْو وهُمْ سَبْعَة مِن الأَنْصار وقِيلَ بَنُو مُقْرِن ﴿قُلْت لا أجِد ما أحْمِلكُمْ عَلَيْهِ﴾ حال ﴿تَوَلَّوْا﴾ جَواب إذا أيْ انْصَرَفُوا ﴿وأَعْيُنهمْ تَفِيض﴾ تَسِيل ﴿مِن﴾ لِلْبَيانِ ﴿الدَّمْع حَزَنًا﴾ لِأَجْلِ ﴿ألّا يَجِدُوا ما يُنْفِقُونَ﴾ فِي الجِهاد"],[93,93,"﴿إنّما السَّبِيل عَلى الَّذِينَ يَسْتَأْذِنُونَك﴾ فِي التَّخَلُّف ﴿وهُمْ أغْنِياء رَضُوا بِأَنْ يَكُونُوا مَعَ الخَوالِف وطَبَعَ اللَّه عَلى قُلُوبهمْ فَهُمْ لا يَعْلَمُونَ﴾ تَقَدَّمَ مِثْله"],[94,94,"﴿يَعْتَذِرُونَ إلَيْكُمْ﴾ فِي التَّخَلُّف ﴿إذا رَجَعْتُمْ إلَيْهِمْ﴾ مِن الغَزْو ﴿قُلْ﴾ لَهُمْ ﴿لا تَعْتَذِرُوا لَنْ نُؤْمِن لَكُمْ﴾ نُصَدِّقكُمْ ﴿قَدْ نَبَّأَنا اللَّه مِن أخْباركُمْ﴾ أيْ أخْبَرَنا بِأَحْوالِكُمْ ﴿وسَيَرى اللَّه عَمَلكُمْ ورَسُوله ثُمَّ تُرَدُّونَ﴾ بِالبَعْثِ ﴿إلى عالِم الغَيْب والشَّهادَة﴾ أيْ اللَّه ﴿فَيُنَبِّئكُمْ بِما كُنْتُمْ تَعْمَلُونَ﴾ فَيُجازِيكُمْ عَلَيْهِ"],[95,95,"﴿سَيَحْلِفُونَ بِاللَّهِ لَكُمْ إذا انْقَلَبْتُمْ﴾ رَجَعْتُمْ ﴿إلَيْهِمْ﴾ مِن تَبُوك أنَّهُمْ مَعْذُورُونَ فِي التَّخَلُّف ﴿لِتُعْرِضُوا عَنْهُمْ﴾ بِتَرْكِ المُعاتَبَة ﴿فَأَعْرِضُوا عَنْهُمْ إنّهُمْ رِجْس﴾ قَذَر لِخُبْثِ باطِنهمْ"],[96,96,"﴿يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْ فَإنْ تَرْضَوْا عَنْهُمْ فَإنَّ اللَّه لا يَرْضى عَنْ القَوْم الفاسِقِينَ﴾ أيْ عَنْهُمْ ولا يَنْفَع رِضاكُمْ مَعَ سَخَط اللَّه"],[97,97,"﴿الأَعْراب﴾ أهْل البَدْو ﴿أشَدّ كُفْرًا ونِفاقًا﴾ مِن أهْل المُدُن لِجَفائِهِمْ وغِلَظ طِباعهمْ وبُعْدهمْ عَنْ سَماع القُرْآن ﴿وأَجْدَر﴾ أوْلى ﴿أن﴾ أيْ بِأَنْ ﴿لا يَعْلَمُوا حُدُود ما أنْزَلَ اللَّه عَلى رَسُوله﴾ مِن الأَحْكام والشَّرائِع ﴿واللَّه عَلِيم﴾ بِخَلْقِهِ ﴿حَكِيم﴾ فِي صُنْعه بِهِمْ"],[98,98,"﴿ومِن الأَعْراب مَن يَتَّخِذ ما يُنْفِق﴾ فِي سَبِيل اللَّه ﴿مَغْرَمًا﴾ غَرامَة وخُسْرانًا لِأَنَّهُ لا يَرْجُو ثَوابه بَلْ يُنْفِقهُ خَوْفًا وهُمْ بَنُو أسَد وغَطَفان ﴿ويَتَرَبَّص﴾ يَنْتَظِر ﴿بِكُمْ الدَّوائِر﴾ دَوائِر الزَّمان أنْ تَنْقَلِب عَلَيْكُمْ فَيَتَخَلَّص ﴿عَلَيْهِمْ دائِرَة السُّوء﴾ بِالضَّمِّ والفَتْح أيْ يَدُور العَذاب والهَلاك عَلَيْهِمْ لا عَلَيْكُمْ ﴿واللَّه سَمِيع﴾ لِأَقْوالِ عِباده ﴿عَلِيم﴾ بِأَفْعالِهِمْ"],[99,99,"﴿ومِن الأَعْراب مَن يُؤْمِن بِاللَّهِ واليَوْم الآخِر﴾ كَجُهَيْنَة ومُزَيْنَةَ ﴿ويَتَّخِذ ما يُنْفِق﴾ فِي سَبِيل اللَّه ﴿قُرُبات﴾ تُقَرِّبهُ ﴿عِنْد اللَّه﴾ وسِيلَة إلى ﴿وصَلَوات﴾ دَعَوات ﴿الرَّسُول﴾ لَهُ ﴿ألا إنّها﴾ أيْ نَفَقَتهمْ ﴿قُرْبَة﴾ بِضَمِّ الرّاء وسُكُونها ﴿لَهُمْ﴾ عِنْده ﴿سَيُدْخِلُهُمْ اللَّه فِي رَحْمَته﴾ جَنَّته ﴿إنّ اللَّه غَفُور﴾ لِأَهْلِ طاعَته ﴿رَحِيم﴾ بِهِمْ"],[100,100,"﴿والسّابِقُونَ الأَوَّلُونَ مِن المُهاجِرِينَ والأَنْصار﴾ وهُمْ مَن شَهِدَ بَدْرًا أوْ جَمِيع الصَّحابَة ﴿والَّذِينَ اتَّبَعُوهُمْ﴾ إلى يَوْم القِيامَة ﴿بِإحْسانٍ﴾ فِي العَمَل ﴿رَضِيَ اللَّه عَنْهُمْ﴾ بِطاعَتِهِ ﴿ورَضُوا عَنْهُ﴾ بِثَوابِهِ ﴿وأَعَدَّ لَهُمْ جَنّات تَجْرِي تَحْتها الأَنْهار﴾ وفِي قِراءَة بِزِيادَةِ مِن"],[101,101,"﴿ومِمَّنْ حَوْلكُمْ﴾ يا أهْل المَدِينَة ﴿مِن الأَعْراب مُنافِقُونَ﴾ كَأَسْلَم وأَشْجَع وغِفار ﴿ومِن أهْل المَدِينَة﴾ مُنافِقُونَ أيْضًا ﴿مَرَدُوا عَلى النِّفاق﴾ لَجُّوا فِيهِ واسْتَمَرُّوا ﴿لا تَعْلَمهُمْ﴾ بِالفَضِيحَةِ أوْ القَتْل فِي الدُّنْيا وعَذاب القَبْر ﴿ثُمَّ يُرَدُّونَ﴾ فِي الآخِرَة ﴿إلى عَذاب عَظِيم﴾ هُوَ النّار"],[102,102,"﴿و﴾ قَوْم ﴿آخَرُونَ﴾ مُبْتَدَأ ﴿اعْتَرَفُوا بِذُنُوبِهِمْ﴾ مِن التَّخَلُّف نَعْته والخَبَر ﴿خَلَطُوا عَمَلًا صالِحًا﴾ وهُوَ جِهادهمْ قَبْل ذَلِكَ أوْ اعْتِرافهمْ بِذُنُوبِهِمْ أوْ غَيْر ذَلِكَ ﴿وآخَر سَيِّئًا﴾ وهُوَ تَخَلُّفهمْ ﴿عَسى اللَّه أنْ يَتُوب عَلَيْهِمْ إنّ اللَّه غَفُور رَحِيم﴾ نَزَلَتْ فِي أبِي لُبابَة وجَماعَة أوْثَقُوا أنْفُسهمْ فِي سَوارِي المَسْجِد لَمّا بَلَغَهُمْ ما نَزَلَ فِي المُتَخَلِّفِينَ وحَلَفُوا لا يُحِلّهُمْ إلّا النَّبِيّ ﷺ فَحَلَّهُمْ لَمّا نَزَلَتْ"],[103,103,"﴿خُذْ مِن أمْوالهمْ صَدَقَة تُطَهِّرهُمْ وتُزَكِّيهِمْ بِها﴾ مِن ذُنُوبهمْ فَأَخَذَ ثُلُث أمْوالهمْ وتَصَدَّقَ بِها ﴿وصَلِّ عَلَيْهِمْ﴾ أيْ اُدْعُ لَهُمْ ﴿إنّ صَلاتك سَكَن لَهُمْ﴾ رَحْمَة وقِيلَ طُمَأْنِينَة بِقَبُولِ تَوْبَتهمْ"],[104,104,"﴿ألَمْ يَعْلَمُوا أنَّ اللَّه هُوَ يَقْبَل التَّوْبَة عَنْ عِباده ويَأْخُذ﴾ يَقْبَل والِاسْتِفْهام لِلتَّقْرِيرِ والقَصْد بِهِ هُوَ تَهْيِيجهمْ إلى التَّوْبَة والصَّدَقَة ﴿الصَّدَقات وأَنَّ اللَّه هُوَ التَّوّاب﴾ عَلى عِباده بِقَبُولِ تَوْبَتهمْ ﴿الرَّحِيم﴾ بِهِمْ"],[105,105,"﴿وقُلْ﴾ لَهُمْ أوْ لِلنّاسِ ﴿اعْمَلُوا﴾ ما شِئْتُمْ ﴿فَسَيَرى اللَّه عَمَلكُمْ ورَسُوله والمُؤْمِنُونَ وسَتُرَدُّونَ﴾ بِالبَعْثِ ﴿إلى عالِم الغَيْب والشَّهادَة﴾ أيْ اللَّه ﴿فَيُنَبِّئكُمْ بِما كُنْتُمْ تَعْمَلُونَ﴾ فَيُجازِيكُمْ بِهِ"],[106,106,"﴿وآخَرُونَ﴾ مِن المُتَخَلِّفِينَ ﴿مُرْجَئُونَ﴾ بِالهَمْزِ وتَرْكه: مُؤَخَّرُونَ عَنْ التَّوْبَة ﴿لِأَمْرِ اللَّه﴾ فِيهِمْ بِما يَشاء ﴿إمّا يُعَذِّبهُمْ﴾ بِأَنْ يُمِيتهُمْ بِلا تَوْبَة ﴿وإمّا يَتُوب عَلَيْهِمْ واللَّه عَلِيم﴾ بِخَلْقِهِ ﴿حَكِيم﴾ فِي صُنْعه بِهِمْ وهُمْ الثَّلاثَة الآتُونَ بَعْد: مَرارَة بْن الرَّبِيع وكَعْب بْن مالِك وهِلال بْن أُمَيَّة تَخَلَّفُوا كَسَلًا ومَيْلًا إلى الدَّعَة لا نِفاقًا ولَمْ يَعْتَذِرُوا إلى النَّبِيّ ﷺ كَغَيْرِهِمْ فَوَقَفَ أمْرهمْ خَمْسِينَ لَيْلَة وهَجَرَهُمْ النّاس حَتّى نَزَلَتْ تَوْبَتهمْ بَعْد"],[107,107,"﴿و﴾ مِنهُمْ ﴿الَّذِينَ اتَّخَذُوا مَسْجِدًا﴾ وهُمْ اثْنا عَشَرَ مِن المُنافِقِينَ ﴿ضِرارًا﴾ مُضارَّة لِأَهْلِ مَسْجِد قُباءَ ﴿وكُفْرًا﴾ لِأَنَّهُمْ بَنَوْهُ بِأَمْرِ أبِي عامِر الرّاهِب لِيَكُونَ مَعْقِلًا لَهُ يَقْدُم فِيهِ مَن يَأْتِي مِن عِنْده وكانَ ذَهَبَ لِيَأْتِيَ بِجُنُودٍ مِن قَيْصَر لِقِتالِ النَّبِيّ ﷺ ﴿وتَفْرِيقًا بَيْن المُؤْمِنِينَ﴾ الَّذِينَ يُصَلُّونَ بِقُباءَ بِصَلاةِ بَعْضهمْ فِي مَسْجِدهمْ ﴿وإرْصادًا﴾ تَرَقُّبًا ﴿لِمَن حارَبَ اللَّه ورَسُوله مِن قَبْل﴾ أيْ قَبْل بِنائِهِ وهُوَ أبُو عامِر المَذْكُور ﴿ولَيَحْلِفُنَّ إنْ﴾ ما ﴿أرَدْنا﴾ بِبِنائِهِ ﴿إلّا﴾ الفِعْلَة ﴿الحُسْنى﴾ مِن الرِّفْق بِالمِسْكِينِ فِي المَطَر والحَرّ والتَّوْسِعَة عَلى المُسْلِمِينَ ﴿واللَّه يَشْهَد إنّهُمْ لَكاذِبُونَ﴾ فِي ذَلِكَ وكانُوا سَأَلُوا النَّبِيّ ﷺ أنْ يُصَلِّي فِيهِ فَنَزَلَ"],[108,108,"﴿لا تَقُمْ﴾ تُصَلِّ ﴿فِيهِ أبَدًا﴾ فَأَرْسَلَ جَماعَة هَدَمُوهُ وحَرَّقُوهُ وجَعَلُوا مَكانه كُناسَة تُلْقى فِيها الجِيَف ﴿لَمَسْجِد أُسِّسَ﴾ بُنِيَتْ قَواعِده ﴿عَلى التَّقْوى مِن أوَّل يَوْم﴾ وُضِعَ يَوْم حَلَلْت بِدارِ الهِجْرَة وهُوَ مَسْجِد قُباءَ كَما فِي البُخارِيّ ﴿أحَقّ﴾ مِنهُ ﴿أنْ﴾ أيْ بِأَنْ ﴿تَقُوم﴾ تُصَلِّي ﴿فِيهِ فِيهِ رِجال﴾ هُمْ الأَنْصار ﴿يُحِبُّونَ أنْ يَتَطَهَّرُوا واللَّه يُحِبّ المُطَّهِّرِينَ﴾ أيْ يُثِيبهُمْ فِيهِ إدْغام التّاء فِي الأَصْل فِي الطّاء رَوى ابْن خُزَيْمَةَ فِي صَحِيحه عَنْ عُوَيْمِر بْن ساعِدَة: \"أنَّهُ ﷺ أتاهُمْ فِي مَسْجِد قُباءَ فَقالَ: إنّ اللَّه تَعالى قَدْ أحْسَنَ عَلَيْكُمْ الثَّناء فِي الطَّهُور فِي قِصَّة مَسْجِدكُمْ فَما هَذا الطَّهُور الَّذِي تَطَّهَّرُونَ بِهِ ؟ قالُوا: واللَّه يا رَسُول اللَّه ما نَعْلَم شَيْئًا إلّا أنَّهُ كانَ لَنا جِيران مِن اليَهُود وكانُوا يَغْسِلُونَ أدْبارهمْ مِن الغائِط فَغَسَلْنا كَما غَسَلُوا\" وفِي حَدِيث رَواهُ البَزّار فَقالُوا نَتْبَع الحِجارَة بِالماءِ \"فَقالَ هُوَ ذاكَ فَعَلَيْكُمُوهُ\""],[109,109,"﴿أفَمَن أسَّسَ بُنْيانه عَلى تَقْوى﴾ مَخافَة ﴿مِن اللَّه و﴾ رَجاء ﴿رِضْوان﴾ مِنهُ ﴿خَيْر أمْ مَن أسَّسَ بُنْيانه عَلى شَفا﴾ طَرَف ﴿جُرُف﴾ بِضَمِّ الرّاء وسُكُونها جانِب ﴿هار﴾ مُشْرِف عَلى السُّقُوط ﴿فانْهارَ بِهِ﴾ سَقَطَ مَعَ بانِيه ﴿فِي نار جَهَنَّم﴾ خَيْر تَمْثِيل لِلْبِناءِ عَلى ضِدّ التَّقْوى بِما يُؤَوَّل إلَيْهِ والِاسْتِفْهام لِلتَّقْرِيرِ أيْ الأَوَّل خَيْر وهُوَ مِثال مَسْجِد قُباءَ والثّانِي مِثال مَسْجِد الضِّرار"],[110,110,"﴿لا يَزال بُنْيانُهُمْ الَّذِي بَنَوْا رِيبَة﴾ شَكًّا ﴿فِي قُلُوبهمْ إلّا أنْ تَقَطَّعَ﴾ تَنْفَصِل ﴿قُلُوبهمْ﴾ بِأَنْ يَمُوتُوا ﴿واللَّه عَلِيم﴾ بِخَلْقِهِ ﴿حَكِيم﴾ فِي صُنْعه بِهِمْ"],[111,111,"﴿إنّ اللَّه اشْتَرى مِن المُؤْمِنِينَ أنْفُسهمْ وأَمْوالهمْ﴾ بِأَنْ يَبْذُلُوها فِي طاعَته كالجِهادِ ﴿بِأَنَّ لَهُمْ الجَنَّة يُقاتِلُونَ فِي سَبِيل اللَّه فَيَقْتُلُونَ ويُقْتَلُونَ﴾ جُمْلَة اسْتِئْناف بَيان لِلشِّراءِ وفِي قِراءَة بِتَقْدِيمِ المَبْنِيّ لِلْمَفْعُولِ أيْ فَيُقْتَل بَعْضهمْ ويُقاتِل الباقِي ﴿وعْدًا عَلَيْهِ حَقًّا﴾ مَصْدَرانِ مَنصُوبانِ بِفِعْلِهِما المَحْذُوف ﴿فِي التَّوْراة والإنْجِيل والقُرْآن ومَن أوْفى بِعَهْدِهِ مِن اللَّه﴾ أيْ لا أحَد أوْفى مِنهُ ﴿فاسْتَبْشِرُوا﴾ فِيهِ التِفات عَنْ الغَيْبَة ﴿بِبَيْعِكُمْ الَّذِي بايَعْتُمْ بِهِ وذَلِك﴾ البَيْع ﴿هُوَ الفَوْز العَظِيم﴾ المُنِيل غايَة المَطْلُوب"],[112,112,"﴿التّائِبُونَ﴾ رُفِعَ عَلى المَدْح بِتَقْدِيرِ مُبْتَدَأ مِن الشِّرْك والنِّفاق ﴿العابِدُونَ﴾ المُخْلِصُونَ العِبادَة لِلَّهِ ﴿الحامِدُونَ﴾ لَهُ عَلى كُلّ حال ﴿السّائِحُونَ﴾ الصّائِمُونَ ﴿الرّاكِعُونَ السّاجِدُونَ﴾ أيْ المُصَلُّونَ ﴿الآمِرُونَ بِالمَعْرُوفِ والنّاهُونَ عَنْ المُنْكَر والحافِظُونَ لِحُدُودِ اللَّه﴾ لِأَحْكامِهِ بِالعَمَلِ بِها ﴿وبَشِّرْ المُؤْمِنِينَ﴾ بِالجَنَّةِ"],[113,113,"ونَزَلَ فِي اسْتِغْفاره ﷺ لِعَمِّهِ أبِي طالِب اسْتِغْفار بَعْض الصَّحابَة لِأَبَوَيْهِ المُشْرِكَيْنِ ﴿ما كانَ لِلنَّبِيِّ والَّذِينَ آمَنُوا أنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ ولَوْ كانُوا أُولِي قُرْبى﴾ ذَوِي قُرْبى ﴿مِن بَعْد ما تَبَيَّنَ لَهُمْ أنَّهُمْ أصْحاب الجَحِيم﴾ النّار بِأَنْ ماتُوا عَلى الكُفْر"],[114,114,"﴿وما كانَ اسْتِغْفار إبْراهِيم لِأَبِيهِ إلّا عَنْ مَوْعِدَة وعَدَها إيّاهُ﴾ بِقَوْلِهِ \"سَأَسْتَغْفِرُ لَك رَبِّي\" رَجاء أنْ يُسْلِم ﴿فَلَمّا تَبَيَّنَ لَهُ أنَّهُ عَدُوّ لِلَّهِ﴾ بِمَوْتِهِ عَلى الكُفْر ﴿تَبَرَّأَ مِنهُ﴾ وتَرَكَ الِاسْتِغْفار لَهُ ﴿إنّ إبْراهِيم لَأَوّاه﴾ كَثِير التَّضَرُّع والدُّعاء ﴿حَلِيم﴾ صَبُور عَلى الأَذى"],[115,115,"﴿وما كانَ اللَّه لِيُضِلّ قَوْمًا بَعْد إذْ هَداهُمْ﴾ لِلْإسْلامِ ﴿حَتّى يُبَيِّن لَهُمْ ما يَتَّقُونَ﴾ مِن العَمَل فَلا يَتَّقُوهُ فَيَسْتَحِقُّوا الإضْلال ﴿إنّ اللَّه بِكُلِّ شَيْء عَلِيم﴾ ومِنهُ مُسْتَحِقّ الإضْلال والهِدايَة"],[116,116,"﴿إنّ اللَّه لَهُ مُلْك السَّمَوات والأَرْض يُحْيِي ويُمِيت وما لَكُمْ﴾ أيّها النّاس ﴿مِن دُون اللَّه﴾ أيْ غَيْره ﴿مِن ولِيّ﴾ يَحْفَظكُمْ مِنهُ ﴿ولا نَصِير﴾ يَمْنَعكُمْ عَنْ ضَرَره"],[117,117,"﴿لَقَدْ تابَ اللَّه﴾ أيْ أدامَ تَوْبَته ﴿عَلى النَّبِيّ والمُهاجِرِينَ والأَنْصار الَّذِينَ اتَّبَعُوهُ فِي ساعَة العُسْرَة﴾ أيْ وقْتها وهِيَ حالهمْ فِي غَزْوَة تَبُوك كانَ الرَّجُلانِ يَقْتَسِمانِ تَمْرَة والعَشَرَة يَعْتَقِبُونَ البَعِير الواحِد واشْتَدَّ الحَرّ حَتّى شَرِبُوا الفَرْث ﴿مِن بَعْد ما كادَ يَزِيغ﴾ بِالتّاءِ والياء تَمِيل ﴿قُلُوب فَرِيق مِنهُمْ﴾ عَنْ اتِّباعه إلى التَّخَلُّف لِما هُمْ فِيهِ مِن الشِّدَّة ﴿ثُمَّ تابَ عَلَيْهِمْ﴾ بِالثَّباتِ"],[118,118,"﴿و﴾ تابَ ﴿عَلى الثَّلاثَة الَّذِينَ خُلِّفُوا﴾ عَنْ التَّوْبَة عَلَيْهِمْ بِقَرِينَةِ ﴿حَتّى إذا ضاقَتْ عَلَيْهِمْ الأَرْض بِما رَحُبَتْ﴾ أيْ مَعَ رَحْبها أيْ سِعَتها فَلا يَجِدُونَ مَكانًا يَطْمَئِنُّونَ إلَيْهِ ﴿وضاقَتْ عَلَيْهِمْ أنْفُسهمْ﴾ قُلُوبهمْ لِلْغَمِّ والوَحْشَة بِتَأْخِيرِ تَوْبَتهمْ فَلا يَسَعها سُرُور ولا أُنْس ﴿وظَنُّوا﴾ أيْقَنُوا ﴿أنْ﴾ مُخَفَّفَة ﴿لا مَلْجَأ مِن اللَّه إلّا إلَيْهِ ثُمَّ تابَ عَلَيْهِمْ﴾ وفَّقَهُمْ لِلتَّوْبَةِ"],[119,119,"﴿يا أيّها الَّذِينَ آمَنُوا اتَّقُوا اللَّه﴾ بِتَرْكِ مَعاصِيه ﴿وكُونُوا مَعَ الصّادِقِين﴾ فِي الإيمان والعُهُود بِأَنْ تَلْزَمُوا الصِّدْق"],[120,120,"﴿ما كانَ لِأَهْلِ المَدِينَة ومَن حَوْلهمْ مِن الأَعْراب أنْ يَتَخَلَّفُوا عَنْ رَسُول اللَّه﴾ إذا غَزا ﴿ولا يَرْغَبُوا بِأَنْفُسِهِمْ عَنْ نَفْسه﴾ بِأَنْ يَصُونُوها عَمّا رَضِيَهُ لِنَفْسِهِ مِن الشَّدائِد وهُوَ نَهْي بِلَفْظِ الخَبَر ﴿ذَلِكَ﴾ أيْ النَّهْي عَنْ التَّخَلُّف\" ﴿﴾ \"بِأَنَّهُمْ\" ﴿بِسَبَبِ أنَّهُمْ﴾ \"لا يُصِيبهُمْ ظَمَأ\" ﴿عَطَش﴾ \"ولا نَصَب\" ﴿تَعَب﴾ \"ولا مَخْمَصَة\" ﴿جُوع﴾ \"فِي سَبِيل اللَّه ولا يَطَئُونَ مَوْطِئًا\" ﴿مَصْدَر بِمَعْنى وطْئًا﴾ \"يَغِيظ\" ﴿يُغْضِب﴾ \"الكُفّار ولا يَنالُونَ مِن عَدُوّ\" ﴿لِلَّهِ﴾ \"نَيْلًا\" ﴿قَتْلًا أوْ أسْرًا أوْ نَهْبًا﴾ \"إلّا كُتِبَ لَهُمْ بِهِ عَمَل صالِح\" ﴿لِيُجازَوْا عَلَيْهِ﴾ \"إنّ اللَّه لا يُضِيع أجْر المُحْسِنِينَ\" ﴿أيْ أجْرهمْ بَلْ يُثِيبهُمْ﴾"],[121,121,"﴿ولا يُنْفِقُونَ﴾ فِيهِ ﴿نَفَقَة صَغِيرَة﴾ ولَوْ تَمْرَة ﴿ولا كَبِيرَة ولا يَقْطَعُونَ وادِيًا﴾ بِالسَّيْرِ ﴿إلّا كُتِبَ لَهُمْ﴾ بِهِ عَمَل صالِح ﴿لِيَجْزِيَهُمْ اللَّه أحْسَن ما كانُوا يَعْمَلُونَ﴾ أيْ جَزاءَهُمْ"],[122,122,"ولَمّا وُبِّخُوا عَلى التَّخَلُّف وأَرْسَلَ النَّبِيّ ﷺ سَرِيَّة نَفَرُوا جَمِيعًا فَنَزَلَ ﴿وما كانَ المُؤْمِنُونَ لِيَنْفِرُوا﴾ إلى الغَزْو ﴿كافَّة فَلَوْلا﴾ فَهَلّا ﴿نَفَرَ مِن كُلّ فِرْقَة﴾ قَبِيلَة ﴿مِنهُمْ طائِفَة﴾ جَماعَة ومَكَثَ الباقُونَ ﴿لِيَتَفَقَّهُوا﴾ أيْ الماكِثُونَ ﴿فِي الدِّين ولِيُنْذِرُوا قَوْمهمْ إذا رَجَعُوا إلَيْهِمْ﴾ مِن الغَزْو بِتَعْلِيمِهِمْ ما تَعَلَّمُوهُ مِن الأَحْكام ﴿لَعَلَّهُمْ يَحْذَرُونَ﴾ عِقاب اللَّه بِامْتِثالِ أمْره ونَهْيه قالَ ابْن عَبّاس فَهَذِهِ مَخْصُوصَة بِالسَّرايا والَّتِي قَبْلها بِالنَّهْيِ عَنْ تَخَلُّف واحِد فِيما إذا خَرَجَ النَّبِيّ ﷺ"],[123,123,"﴿يا أيّها الَّذِينَ آمَنُوا قاتِلُوا الَّذِينَ يَلُونَكُمْ مِن الكُفّار﴾ أيْ الأَقْرَب فالأَقْرَب مِنهُمْ ﴿ولْيَجِدُوا فِيكُمْ غِلْظَة﴾ شِدَّة أيْ أغْلِظُوا عَلَيْهِمْ ﴿واعْلَمُوا أنَّ اللَّه مَعَ المُتَّقِينَ﴾ بِالعَوْنِ والنَّصْر"],[124,124,"﴿وإذا ما أُنْزِلَتْ سُورَة﴾ مِن القُرْآن ﴿فَمِنهُمْ﴾ أيْ المُنافِقِينَ ﴿مَن يَقُول﴾ لِأَصْحابِهِ اسْتِهْزاء ﴿أيّكُمْ زادَتْهُ هَذِهِ إيمانًا﴾ تَصْدِيقًا ﴿فَأَمّا الَّذِينَ آمَنُوا فَزادَتْهُمْ إيمانًا﴾ لِتَصْدِيقِهِمْ بِها ﴿وهُمْ يَسْتَبْشِرُونَ﴾ يَفْرَحُونَ بِها"],[125,125,"﴿وأَمّا الَّذِينَ فِي قُلُوبهمْ مَرَض﴾ ضَعْف اعْتِقاد ﴿فَزادَتْهُمْ رِجْسًا إلى رِجْسهمْ﴾ كُفْرًا إلى كُفْرهمْ لِكُفْرِهِمْ بِها"],[126,126,"﴿أوَلا يَرَوْنَ﴾ بِالياءِ أيْ المُنافِقُونَ والتّاء أيّها المُؤْمِنُونَ ﴿أنَّهُمْ يُفْتَنُونَ﴾ يُبْتَلَوْنَ ﴿فِي كُلّ عام مَرَّة أوْ مَرَّتَيْنِ﴾ بِالقَحْطِ والأَمْراض ﴿ثُمَّ لا يَتُوبُونَ﴾ مِن نِفاقهمْ ﴿ولا هُمْ يَذَّكَّرُونَ﴾ يَتَّعِظُونَ"],[127,127,"وإذا ما أُنْزِلَتْ سُورَة\" ﴿فِيها ذِكْرهمْ وقَرَأَها النَّبِيّ ﷺ﴾ \"نَظَرَ بَعْضهمْ إلى بَعْض\" ﴿يُرِيدُونَ الهَرَب يَقُولُونَ:﴾ \"هَلْ يَراكُمْ مِن أحَد\" ﴿إذا قُمْتُمْ فَإنْ لَمْ يَرَهُمْ أحَد قامُوا وإلّا ثَبَتُوا﴾ \"ثُمَّ انْصَرَفُوا\" ﴿عَلى كُفْرهمْ﴾ \"صَرَفَ اللَّه قُلُوبهمْ\" ﴿عَنْ الهُدى﴾ \"بِأَنَّهُمْ قَوْم لا يَفْقَهُونَ\" ﴿الحَقّ لِعَدَمِ تَدَبُّرهمْ﴾"],[128,128,"﴿لَقَدْ جاءَكُمْ رَسُول مِن أنْفُسكُمْ﴾ أيْ مِنكُمْ: مُحَمَّد ﷺ ﴿عَزِيز﴾ شَدِيد ﴿عَلَيْهِ ما عَنِتُّمْ﴾ أيْ عَنَتكُمْ أيْ مَشَقَّتكُمْ ولِقاؤُكُمْ المَكْرُوه ﴿حَرِيص عَلَيْكُمْ﴾ أنْ تَهْتَدُوا ﴿بِالمُؤْمِنِينَ رَءُوف﴾ شَدِيد الرَّحْمَة ﴿رَحِيم﴾ يُرِيد لَهُمْ الخَيْر"],[129,129,"﴿فَإنْ تَوَلَّوْا﴾ عَنْ الإيمان بِك ﴿فَقُلْ حَسْبِي اللَّه﴾ كافِي ﴿لا إلَه إلّا هُوَ عَلَيْهِ تَوَكَّلْت﴾ بِهِ وثِقْت لا بِغَيْرِهِ ﴿وهُوَ رَبّ العَرْش﴾ الكُرْسِيّ ﴿العَظِيم﴾ خَصَّهُ بِالذِّكْرِ لِأَنَّهُ أعْظَم المَخْلُوقات ورَوى الحاكِم فِي المُسْتَدْرَك عَنْ أُبَيّ بْن كَعْب قالَ: آخِر آيَة نَزَلَتْ ﴿لَقَدْ جاءَكُمْ رَسُول﴾ إلى آخِر السُّورَة"]]};
